#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum NativeRequestStateBag {
    Server,
    Get,
    Post,
    Cookie,
    Request,
    Files,
    Session,
    Env,
}

impl NativeRequestStateBag {
    fn from_abi_bytes(value: &[u8]) -> Option<Self> {
        Some(match value {
            b"_SERVER" => Self::Server,
            b"_GET" => Self::Get,
            b"_POST" => Self::Post,
            b"_COOKIE" => Self::Cookie,
            b"_REQUEST" => Self::Request,
            b"_FILES" => Self::Files,
            b"_SESSION" => Self::Session,
            b"_ENV" => Self::Env,
            _ => return None,
        })
    }

    fn supports_keyed_scalar_snapshot(self) -> bool {
        matches!(
            self,
            Self::Server | Self::Get | Self::Post | Self::Cookie | Self::Request | Self::Env
        )
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeRequestStateOperationKind {
    Value,
    Array,
    Presence,
    BagPresence,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeRequestStateMutationKind {
    Write,
    Unset,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeRequestStateOperationAddressFamily {
    KeyedScalarSnapshot,
    BagSnapshot,
}

impl NativeRequestStateOperationKind {
    fn from_abi_tag(value: u8) -> Option<Self> {
        Some(match value {
            PHPC_NATIVE_REQUEST_STATE_OP_VALUE => Self::Value,
            PHPC_NATIVE_REQUEST_STATE_OP_ARRAY => Self::Array,
            PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE => Self::Presence,
            PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE => Self::BagPresence,
            _ => return None,
        })
    }

    fn address_family(self) -> NativeRequestStateOperationAddressFamily {
        match self {
            Self::Value | Self::Presence => {
                NativeRequestStateOperationAddressFamily::KeyedScalarSnapshot
            }
            Self::Array | Self::BagPresence => {
                NativeRequestStateOperationAddressFamily::BagSnapshot
            }
        }
    }

    fn uses_keyed_scalar_snapshot(self) -> bool {
        matches!(
            self.address_family(),
            NativeRequestStateOperationAddressFamily::KeyedScalarSnapshot
        )
    }

    fn uses_bag_snapshot(self) -> bool {
        matches!(
            self.address_family(),
            NativeRequestStateOperationAddressFamily::BagSnapshot
        )
    }

    fn owns_value_handle(self) -> bool {
        matches!(self, Self::Value)
    }

    fn owns_array_handle(self) -> bool {
        matches!(self, Self::Array)
    }

    fn owns_runtime_handle(self) -> bool {
        self.owns_value_handle() || self.owns_array_handle()
    }

    fn reports_missing_key_diagnostic(self) -> bool {
        self.owns_runtime_handle()
    }
}

impl NativeRequestStateMutationKind {
    fn from_abi_tag(value: u8) -> Option<Self> {
        Some(match value {
            PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE => Self::Write,
            PHPC_NATIVE_REQUEST_STATE_MUTATION_UNSET => Self::Unset,
            _ => return None,
        })
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NativeRequestStateOperationStatus {
    Ok,
    MissingKey,
    InvalidOperation,
    InvalidAbi,
    NullState,
    UnknownBag,
    UnsupportedKeyedBag,
    UnsupportedKeyCoercion,
    UnsupportedKeyedValue,
}

impl NativeRequestStateOperationStatus {
    fn from_abi_tag(value: u8) -> Option<Self> {
        Some(match value {
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK => Self::Ok,
            PHPC_NATIVE_REQUEST_STATE_STATUS_MISSING_KEY => Self::MissingKey,
            PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_OPERATION => Self::InvalidOperation,
            PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_ABI => Self::InvalidAbi,
            PHPC_NATIVE_REQUEST_STATE_STATUS_NULL_STATE => Self::NullState,
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNKNOWN_BAG => Self::UnknownBag,
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_BAG => Self::UnsupportedKeyedBag,
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEY_COERCION => {
                Self::UnsupportedKeyCoercion
            }
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_VALUE => Self::UnsupportedKeyedValue,
            _ => return None,
        })
    }

    fn abi_tag(self) -> u8 {
        match self {
            Self::Ok => PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
            Self::MissingKey => PHPC_NATIVE_REQUEST_STATE_STATUS_MISSING_KEY,
            Self::InvalidOperation => PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_OPERATION,
            Self::InvalidAbi => PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_ABI,
            Self::NullState => PHPC_NATIVE_REQUEST_STATE_STATUS_NULL_STATE,
            Self::UnknownBag => PHPC_NATIVE_REQUEST_STATE_STATUS_UNKNOWN_BAG,
            Self::UnsupportedKeyedBag => PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_BAG,
            Self::UnsupportedKeyCoercion => {
                PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEY_COERCION
            }
            Self::UnsupportedKeyedValue => PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_VALUE,
        }
    }

    fn diagnostic_message(self) -> Option<&'static str> {
        match self {
            Self::Ok | Self::MissingKey => None,
            Self::InvalidOperation => {
                Some("native request-state operation failed: invalid operation tag")
            }
            Self::InvalidAbi => Some("native request-state operation failed: invalid ABI operands"),
            Self::NullState => Some("native request-state operation failed: null request state"),
            Self::UnknownBag => Some("native request-state operation failed: unknown request bag"),
            Self::UnsupportedKeyedBag => Some(
                "native request-state operation failed: keyed access is not supported for this request bag",
            ),
            Self::UnsupportedKeyCoercion => {
                Some("native request-state operation failed: unsupported PHP key coercion")
            }
            Self::UnsupportedKeyedValue => Some(
                "native request-state operation failed: keyed request-state value is not array-accessible",
            ),
        }
    }
}

enum NativeRequestStateOperation<'a> {
    Keyed {
        request_state: &'a NativeRequestState,
        bag: NativeRequestStateBag,
        key: &'a [u8],
    },
    KeyPath {
        request_state: &'a NativeRequestState,
        bag: NativeRequestStateBag,
        keys: Vec<ArrayKey>,
    },
    Bag {
        request_state: &'a NativeRequestState,
        bag: NativeRequestStateBag,
    },
}

enum NativeRequestStateMutation<'a> {
    Keyed {
        request_state: &'a mut NativeRequestState,
        bag: NativeRequestStateBag,
        key: ArrayKey,
    },
    KeyPath {
        request_state: &'a mut NativeRequestState,
        bag: NativeRequestStateBag,
        keys: Vec<ArrayKey>,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct PhpStringByteView<'a> {
    bytes: &'a [u8],
}

trait PhpStringByteSource {
    fn string_byte_view(&self) -> Option<PhpStringByteView<'_>>;

    fn string_bytes(&self) -> Option<&[u8]> {
        self.string_byte_view().map(|bytes| bytes.as_slice())
    }

    fn string_clone_native_byte_buffer(&self) -> Option<NativeByteBuffer> {
        self.string_byte_view()
            .map(PhpStringByteView::clone_native_byte_buffer)
    }

    fn string_clone_native_handle(&self) -> Option<NativeStringHandle> {
        self.string_byte_view()
            .map(PhpStringByteView::clone_native_string_handle)
    }

    fn write_string_bytes_to<W: Write>(&self, writer: &mut W) -> Option<io::Result<usize>> {
        self.string_byte_view().map(|bytes| bytes.write_to(writer))
    }

    /// # Safety
    ///
    /// `buffer` must either be null or point to at least `capacity` writable
    /// bytes. The function returns the full byte length required by the source,
    /// even when the supplied buffer is smaller.
    unsafe fn write_string_bytes_to_raw_buffer(
        &self,
        buffer: *mut u8,
        capacity: usize,
    ) -> Option<usize> {
        self.string_byte_view()
            .map(|bytes| unsafe { bytes.write_to_raw_buffer(buffer, capacity) })
    }
}

impl<'a> PhpStringByteView<'a> {
    fn from_slice(bytes: &'a [u8]) -> Self {
        Self { bytes }
    }

    fn as_slice(self) -> &'a [u8] {
        self.bytes
    }

    fn clone_native_byte_buffer(self) -> NativeByteBuffer {
        NativeByteBuffer::from_slice(self.bytes)
    }

    fn clone_native_string_handle(self) -> NativeStringHandle {
        NativeStringHandle::from_vec(self.bytes.to_vec())
    }

    fn write_to<W: Write>(self, writer: &mut W) -> io::Result<usize> {
        writer.write_all(self.bytes)?;
        Ok(self.bytes.len())
    }

    /// # Safety
    ///
    /// `buffer` must either be null or point to at least `capacity` writable
    /// bytes. The function returns the full byte length required by this view,
    /// even when the supplied buffer is smaller.
    unsafe fn write_to_raw_buffer(self, buffer: *mut u8, capacity: usize) -> usize {
        let required = self.bytes.len();
        if buffer.is_null() || capacity == 0 {
            return required;
        }

        let written = required.min(capacity);
        unsafe { ptr::copy_nonoverlapping(self.bytes.as_ptr(), buffer, written) };
        required
    }
}

impl PhpStringByteSource for str {
    fn string_byte_view(&self) -> Option<PhpStringByteView<'_>> {
        Some(PhpStringByteView::from_slice(self.as_bytes()))
    }
}

impl PhpStringByteSource for NativeString {
    fn string_byte_view(&self) -> Option<PhpStringByteView<'_>> {
        Some(PhpStringByteView::from_slice(&self.bytes))
    }
}

impl PhpStringByteSource for NativeDiagnostic {
    fn string_byte_view(&self) -> Option<PhpStringByteView<'_>> {
        Some(PhpStringByteView::from_slice(self.message.as_bytes()))
    }
}

impl NativeByteBuffer {
    pub const fn empty() -> Self {
        Self {
            ptr: ptr::null_mut(),
            len: 0,
            cap: 0,
        }
    }

    pub fn from_vec(mut bytes: Vec<u8>) -> Self {
        if bytes.is_empty() {
            return Self::empty();
        }

        let buffer = Self {
            ptr: bytes.as_mut_ptr(),
            len: bytes.len(),
            cap: bytes.capacity(),
        };
        std::mem::forget(bytes);
        buffer
    }

    pub fn from_slice(bytes: &[u8]) -> Self {
        Self::from_vec(bytes.to_vec())
    }

    pub fn ptr(&self) -> *mut u8 {
        self.ptr
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn cap(&self) -> usize {
        self.cap
    }
}

impl NativeStringHandle {
    pub const fn null() -> Self {
        Self {
            ptr: ptr::null_mut(),
        }
    }

    pub fn from_vec(bytes: Vec<u8>) -> Self {
        Self {
            ptr: Box::into_raw(Box::new(NativeString { bytes })),
        }
    }

    pub fn is_null(&self) -> bool {
        self.ptr.is_null()
    }

    unsafe fn as_ref(&self) -> Option<&NativeString> {
        unsafe { self.ptr.as_ref() }
    }
}

impl NativeValueHandle {
    pub const fn null() -> Self {
        Self {
            ptr: ptr::null_mut(),
        }
    }

    pub fn from_value(value: Value) -> Self {
        Self {
            ptr: Box::into_raw(Box::new(value)),
        }
    }

    pub fn is_null(&self) -> bool {
        self.ptr.is_null()
    }

    unsafe fn as_ref(&self) -> Option<&Value> {
        unsafe { self.ptr.as_ref() }
    }

    unsafe fn as_mut(&mut self) -> Option<&mut Value> {
        unsafe { self.ptr.as_mut() }
    }
}

impl NativeDiagnosticHandle {
    pub const fn null() -> Self {
        Self {
            ptr: ptr::null_mut(),
        }
    }

    fn from_message(message: impl Into<String>) -> Self {
        Self::from_message_with_severity(NativeDiagnosticSeverity::Error, message)
    }

    fn from_blocker_message(message: impl Into<String>) -> Self {
        Self::from_message_with_severity(NativeDiagnosticSeverity::Blocker, message)
    }

    fn from_message_with_severity(
        severity: NativeDiagnosticSeverity,
        message: impl Into<String>,
    ) -> Self {
        Self {
            ptr: Box::into_raw(Box::new(NativeDiagnostic {
                severity,
                message: message.into(),
                source_location: None,
            })),
        }
    }

    fn clone_with_source_location(self, source_location: NativeDiagnosticSourceLocation) -> Self {
        unsafe { self.as_ref() }
            .cloned()
            .map(|mut diagnostic| {
                diagnostic.source_location = Some(source_location);
                Self {
                    ptr: Box::into_raw(Box::new(diagnostic)),
                }
            })
            .unwrap_or_else(Self::null)
    }

    pub fn is_null(&self) -> bool {
        self.ptr.is_null()
    }

    unsafe fn as_ref(&self) -> Option<&NativeDiagnostic> {
        unsafe { self.ptr.as_ref() }
    }
}

impl NativeStringConversionResult {
    fn success(bytes: Vec<u8>) -> Self {
        Self {
            bytes: NativeByteBuffer::from_vec(bytes),
            diagnostic: NativeDiagnosticHandle::null(),
        }
    }

    fn failure(error: RuntimeError) -> Self {
        Self {
            bytes: NativeByteBuffer::empty(),
            diagnostic: NativeDiagnosticHandle::from_message(error.message()),
        }
    }

    pub fn is_success(&self) -> bool {
        self.diagnostic.is_null()
    }
}

impl NativeDiagnosticSeverity {
    pub const fn tag(self) -> u8 {
        self as u8
    }

    pub const fn mask(self) -> u32 {
        1_u32 << ((self as u8) - 1)
    }

    fn from_abi_tag(tag: u8) -> Option<Self> {
        match tag {
            1 => Some(Self::Notice),
            2 => Some(Self::Warning),
            3 => Some(Self::Error),
            4 => Some(Self::Blocker),
            _ => None,
        }
    }
}

impl NativeArrayKeyMaterializationResult {
    fn int(value: i64) -> Self {
        Self {
            tag: NativeArrayKeyMaterializationTag::Int,
            int_value: value,
            bytes: NativeByteBuffer::empty(),
            diagnostic: NativeDiagnosticHandle::null(),
        }
    }

    fn string_source(source: &impl PhpStringByteSource) -> Self {
        Self {
            tag: NativeArrayKeyMaterializationTag::String,
            int_value: 0,
            bytes: source
                .string_bytes()
                .map(NativeByteBuffer::from_slice)
                .unwrap_or_else(NativeByteBuffer::empty),
            diagnostic: NativeDiagnosticHandle::null(),
        }
    }

    fn failure(error: RuntimeError) -> Self {
        Self {
            tag: NativeArrayKeyMaterializationTag::Error,
            int_value: 0,
            bytes: NativeByteBuffer::empty(),
            diagnostic: NativeDiagnosticHandle::from_message(error.message()),
        }
    }

    fn from_array_key(key: ArrayKey) -> Self {
        match &key {
            ArrayKey::Int(value) => Self::int(*value),
            ArrayKey::String(_) => Self::string_source(&key),
        }
    }
}

impl NativeValueOperationResult {
    fn value(value: Value) -> Self {
        Self {
            tag: NativeValueOperationResultTag::Ok,
            value: NativeValueHandle::from_value(value),
            diagnostic: NativeDiagnosticHandle::null(),
        }
    }

    fn diagnostic(message: impl Into<String>) -> Self {
        Self {
            tag: NativeValueOperationResultTag::Error,
            value: NativeValueHandle::null(),
            diagnostic: NativeDiagnosticHandle::from_message(message),
        }
    }

    #[cfg(test)]
    fn succeeded(&self) -> bool {
        self.tag == NativeValueOperationResultTag::Ok
    }
}

impl NativeComparisonResult {
    pub fn ok(value: bool) -> Self {
        Self {
            status: NativeComparisonStatus::Ok as u8,
            value: value as u8,
            diagnostic: NativeDiagnosticHandle::null(),
        }
    }

    fn blocked_comparison(blocker: ComparisonBlocker) -> Self {
        NativeComparisonOutcome::blocked_comparison(blocker).into_native_result()
    }

    fn blocked(message: impl Into<String>) -> Self {
        Self {
            status: NativeComparisonStatus::Blocked as u8,
            value: 0,
            diagnostic: NativeDiagnosticHandle::from_blocker_message(message),
        }
    }

    fn blocked_with_diagnostic(diagnostic: NativeDiagnosticHandle) -> Self {
        Self {
            status: NativeComparisonStatus::Blocked as u8,
            value: 0,
            diagnostic,
        }
    }

    pub fn status(&self) -> u8 {
        if self.is_ok() {
            NativeComparisonStatus::Ok as u8
        } else {
            NativeComparisonStatus::Blocked as u8
        }
    }

    pub fn value(&self) -> bool {
        self.is_ok() && self.value != 0
    }

    pub fn diagnostic(&self) -> NativeDiagnosticHandle {
        self.diagnostic
    }

    pub fn is_blocked(&self) -> bool {
        self.status() == NativeComparisonStatus::Blocked as u8
    }

    pub fn is_true(&self) -> bool {
        !self.is_blocked() && self.value != 0
    }

    pub fn exit_code(&self) -> i32 {
        if self.is_blocked() {
            1
        } else {
            0
        }
    }

    pub fn is_ok(&self) -> bool {
        self.status == NativeComparisonStatus::Ok as u8
    }
}

impl NativeComparisonRelation {
    fn from_relation(relation: ComparisonRelation) -> Self {
        match relation {
            ComparisonRelation::Equal => Self::Equal,
            ComparisonRelation::Different => Self::Different,
            ComparisonRelation::Less => Self::Less,
            ComparisonRelation::Greater => Self::Greater,
            ComparisonRelation::Unordered => Self::Unordered,
        }
    }

    fn from_abi(tag: u8) -> Option<Self> {
        Some(match tag {
            value if value == Self::Equal as u8 => Self::Equal,
            value if value == Self::Different as u8 => Self::Different,
            value if value == Self::Less as u8 => Self::Less,
            value if value == Self::Greater as u8 => Self::Greater,
            value if value == Self::Unordered as u8 => Self::Unordered,
            _ => return None,
        })
    }

    fn satisfies(self, op: PhpComparisonOp) -> bool {
        match op {
            PhpComparisonOp::LooseEq => self == Self::Equal,
            PhpComparisonOp::LooseNe => self != Self::Equal,
            PhpComparisonOp::LooseLt => self == Self::Less,
            PhpComparisonOp::LooseLe => matches!(self, Self::Less | Self::Equal),
            PhpComparisonOp::LooseGt => self == Self::Greater,
            PhpComparisonOp::LooseGe => matches!(self, Self::Greater | Self::Equal),
            PhpComparisonOp::StrictEq => self == Self::Equal,
            PhpComparisonOp::StrictNe => self == Self::Different,
        }
    }
}

impl NativeComparisonRelationResult {
    fn ok(relation: ComparisonRelation, operation: NativeComparisonOperation) -> Self {
        Self {
            status: NativeComparisonStatus::Ok as u8,
            relation: NativeComparisonRelation::from_relation(relation) as u8,
            family: operation.family().abi_tag(),
            diagnostic: NativeDiagnosticHandle::null(),
        }
    }

    fn blocked(message: impl Into<String>, operation: NativeComparisonOperation) -> Self {
        Self::blocked_with_diagnostic(
            NativeDiagnosticHandle::from_blocker_message(message),
            operation.family(),
        )
    }

    fn blocked_with_diagnostic(
        diagnostic: NativeDiagnosticHandle,
        family: NativeComparisonOperationFamily,
    ) -> Self {
        Self {
            status: NativeComparisonStatus::Blocked as u8,
            relation: NativeComparisonRelation::Unordered as u8,
            family: family.abi_tag(),
            diagnostic,
        }
    }

    fn from_evaluation(
        evaluation: RuntimeResult<ComparisonRelationEvaluation>,
        operation: NativeComparisonOperation,
    ) -> Self {
        match evaluation {
            Ok(ComparisonRelationEvaluation::Relation(relation)) => Self::ok(relation, operation),
            Ok(ComparisonRelationEvaluation::Blocked(blocker)) => {
                Self::blocked(blocker.native_diagnostic_message(), operation)
            }
            Err(error) => Self::blocked(
                format!("native comparison failed: {}", error.message()),
                operation,
            ),
        }
    }

    fn status(&self) -> u8 {
        if self.status == NativeComparisonStatus::Ok as u8 {
            NativeComparisonStatus::Ok as u8
        } else {
            NativeComparisonStatus::Blocked as u8
        }
    }

    fn relation(&self) -> Option<NativeComparisonRelation> {
        NativeComparisonRelation::from_abi(self.relation)
    }

    fn family(&self) -> Option<NativeComparisonOperationFamily> {
        NativeComparisonOperationFamily::from_abi_tag(self.family)
    }

    fn diagnostic(&self) -> NativeDiagnosticHandle {
        self.diagnostic
    }

    fn is_blocked(&self) -> bool {
        self.status() == NativeComparisonStatus::Blocked as u8
    }

    fn into_native_result(self, operation: NativeComparisonOperation) -> NativeComparisonResult {
        if self.is_blocked() {
            return NativeComparisonResult::blocked_with_diagnostic(self.diagnostic());
        }

        let op = match operation.php_operation() {
            Ok(op) => op,
            Err(outcome) => return outcome.into_native_result(),
        };
        let Some(relation) = self.relation() else {
            return NativeComparisonResult::blocked(
                "native comparison failed: relation result carried an invalid relation tag",
            );
        };
        let expected_family = operation.family();
        if self.family() != Some(expected_family) {
            return NativeComparisonResult::blocked(
                "native comparison failed: relation result family does not match comparison operation",
            );
        }

        NativeComparisonResult::ok(relation.satisfies(op))
    }
}

impl NativeComparisonOp {
    pub const ALL: [Self; 8] = [
        Self::LooseEq,
        Self::LooseNe,
        Self::LooseLt,
        Self::LooseLe,
        Self::LooseGt,
        Self::LooseGe,
        Self::StrictEq,
        Self::StrictNe,
    ];

    pub const fn abi_opcode(self) -> u8 {
        self as u8
    }

    pub fn from_abi(op: u8) -> Option<Self> {
        Some(match op {
            value if value == Self::LooseEq.abi_opcode() => Self::LooseEq,
            value if value == Self::LooseNe.abi_opcode() => Self::LooseNe,
            value if value == Self::LooseLt.abi_opcode() => Self::LooseLt,
            value if value == Self::LooseLe.abi_opcode() => Self::LooseLe,
            value if value == Self::LooseGt.abi_opcode() => Self::LooseGt,
            value if value == Self::LooseGe.abi_opcode() => Self::LooseGe,
            value if value == Self::StrictEq.abi_opcode() => Self::StrictEq,
            value if value == Self::StrictNe.abi_opcode() => Self::StrictNe,
            _ => return None,
        })
    }

    fn php_operation(self) -> PhpComparisonOp {
        match self {
            Self::LooseEq => PhpComparisonOp::LooseEq,
            Self::LooseNe => PhpComparisonOp::LooseNe,
            Self::LooseLt => PhpComparisonOp::LooseLt,
            Self::LooseLe => PhpComparisonOp::LooseLe,
            Self::LooseGt => PhpComparisonOp::LooseGt,
            Self::LooseGe => PhpComparisonOp::LooseGe,
            Self::StrictEq => PhpComparisonOp::StrictEq,
            Self::StrictNe => PhpComparisonOp::StrictNe,
        }
    }
}

impl NativeComparisonOperationFamily {
    pub const fn abi_tag(self) -> u8 {
        self as u8
    }

    fn from_abi_tag(tag: u8) -> Option<Self> {
        Some(match tag {
            value if value == Self::Invalid as u8 => Self::Invalid,
            value if value == Self::LooseEquality as u8 => Self::LooseEquality,
            value if value == Self::LooseOrdering as u8 => Self::LooseOrdering,
            value if value == Self::StrictIdentity as u8 => Self::StrictIdentity,
            _ => return None,
        })
    }

    fn from_operation_family(family: ComparisonOperationFamily) -> Self {
        match family {
            ComparisonOperationFamily::LooseEquality(_) => Self::LooseEquality,
            ComparisonOperationFamily::LooseOrdering(_) => Self::LooseOrdering,
            ComparisonOperationFamily::StrictIdentity { .. } => Self::StrictIdentity,
        }
    }
}

impl NativeComparisonOperation {
    pub fn from_opcode(opcode: u8) -> Self {
        Self {
            opcode,
            valid: u8::from(NativeComparisonOp::from_abi(opcode).is_some()),
        }
    }

    pub const fn opcode(&self) -> u8 {
        self.opcode
    }

    pub fn is_valid(&self) -> bool {
        self.native_op().is_some()
    }

    pub fn family(&self) -> NativeComparisonOperationFamily {
        self.native_op()
            .map(|op| {
                NativeComparisonOperationFamily::from_operation_family(
                    op.php_operation().operation_family(),
                )
            })
            .unwrap_or(NativeComparisonOperationFamily::Invalid)
    }

    fn native_op(&self) -> Option<NativeComparisonOp> {
        if self.valid == 0 {
            return None;
        }

        NativeComparisonOp::from_abi(self.opcode)
    }

    fn php_operation(self) -> Result<PhpComparisonOp, NativeComparisonOutcome> {
        self.native_op()
            .map(NativeComparisonOp::php_operation)
            .ok_or_else(|| NativeComparisonOutcome::blocked_unsupported_opcode(self.opcode))
    }
}

impl NativeComparisonOperand {
    pub const fn from_parts(value: NativeValueHandle, diagnostic: NativeDiagnosticHandle) -> Self {
        Self { value, diagnostic }
    }

    pub const fn value(&self) -> NativeValueHandle {
        self.value
    }

    pub const fn diagnostic(&self) -> NativeDiagnosticHandle {
        self.diagnostic
    }
}

impl NativeComparisonBranchResult {
    fn ok(value: bool) -> Self {
        Self {
            status: NativeComparisonStatus::Ok as u8,
            value: u8::from(value),
            diagnostic_len: 0,
        }
    }

    fn blocked(diagnostic_len: usize) -> Self {
        Self {
            status: NativeComparisonStatus::Blocked as u8,
            value: 0,
            diagnostic_len,
        }
    }

    pub fn status(&self) -> u8 {
        if self.status == NativeComparisonStatus::Ok as u8 {
            NativeComparisonStatus::Ok as u8
        } else {
            NativeComparisonStatus::Blocked as u8
        }
    }

    pub fn value(&self) -> bool {
        self.is_true()
    }

    pub fn diagnostic_len(&self) -> usize {
        self.diagnostic_len
    }

    pub fn is_blocked(&self) -> bool {
        self.status() == NativeComparisonStatus::Blocked as u8
    }

    pub fn is_true(&self) -> bool {
        !self.is_blocked() && self.value != 0
    }

    pub fn exit_code(&self) -> i32 {
        if self.is_blocked() {
            1
        } else {
            0
        }
    }
}

impl NativeComparisonBranchDecision {
    fn from_branch_result(result: NativeComparisonBranchResult) -> Self {
        Self {
            exit_code: result.exit_code(),
            value: u8::from(result.is_true()),
        }
    }

    pub fn status(&self) -> u8 {
        if self.exit_code == 0 {
            NativeComparisonStatus::Ok as u8
        } else {
            NativeComparisonStatus::Blocked as u8
        }
    }

    pub fn exit_code(&self) -> c_int {
        self.exit_code
    }

    pub fn is_blocked(&self) -> bool {
        self.status() == NativeComparisonStatus::Blocked as u8
    }

    pub fn abort_code(&self) -> c_int {
        if self.is_blocked() {
            self.exit_code()
        } else {
            0
        }
    }

    pub fn is_true(&self) -> bool {
        self.exit_code == 0 && self.value != 0
    }
}

fn native_comparison_branch_state_result_operand(
    status: u8,
    value: bool,
    blocked_message: impl Into<String>,
) -> NativeComparisonOperand {
    if status == NativeComparisonStatus::Ok as u8 {
        return phpc_native_comparison_operand_from_scalar(NativeScalarValue::bool(value));
    }

    NativeComparisonOperand::from_parts(
        NativeValueHandle::null(),
        NativeDiagnosticHandle::from_message(blocked_message),
    )
}

#[no_mangle]
pub extern "C" fn phpc_native_comparison_branch_decision_result_operand(
    decision: NativeComparisonBranchDecision,
) -> NativeComparisonOperand {
    native_comparison_branch_state_result_operand(
        decision.status(),
        decision.is_true(),
        "native comparison failed: comparison branch decision is blocked",
    )
}

