impl NativeRequestState {
    fn empty() -> Self {
        Self {
            superglobals: HashMap::new(),
            root_values: HashMap::new(),
        }
    }

    fn insert_superglobal_value(
        &mut self,
        bag: NativeRequestStateBag,
        key: impl AsRef<[u8]>,
        value: Value,
    ) -> bool {
        let Some(key) = request_state_array_key(key.as_ref()) else {
            return false;
        };
        self.root_values.remove(&bag);
        self.superglobals.entry(bag).or_default().insert(key, value);
        true
    }

    fn superglobal_value(
        &self,
        bag: NativeRequestStateBag,
        key: &[u8],
    ) -> Result<Option<Value>, NativeRequestStateOperationStatus> {
        let key =
            request_state_array_key(key).ok_or(NativeRequestStateOperationStatus::InvalidAbi)?;
        if let Some(root_value) = self.root_values.get(&bag).map(ArraySlot::value_cloned) {
            return request_state_get_path_cloned_from_root(&root_value, &[key]);
        }
        Ok(self
            .superglobals
            .get(&bag)
            .and_then(|values| values.get_cloned(key)))
    }

    fn superglobal_path_value(
        &self,
        bag: NativeRequestStateBag,
        keys: &[ArrayKey],
    ) -> Result<Option<Value>, NativeRequestStateOperationStatus> {
        if let Some(root_value) = self.root_values.get(&bag).map(ArraySlot::value_cloned) {
            return request_state_get_path_cloned_from_root(&root_value, keys);
        }
        let Some(values) = self.superglobals.get(&bag) else {
            return Ok(None);
        };

        request_state_get_path_cloned(values, keys)
    }

    fn superglobal_runtime_value(&self, bag: NativeRequestStateBag, key: &[u8]) -> Value {
        self.superglobal_value(bag, key)
            .ok()
            .flatten()
            .unwrap_or(Value::Null)
    }

    fn superglobal_array(&self, bag: NativeRequestStateBag) -> PhpArray {
        self.superglobals
            .get(&bag)
            .cloned()
            .unwrap_or_else(PhpArray::new)
    }

    fn superglobal_snapshot_value(&self, bag: NativeRequestStateBag) -> Value {
        self.root_values
            .get(&bag)
            .map(ArraySlot::value_cloned)
            .unwrap_or_else(|| Value::Array(self.superglobal_array(bag)))
    }

    fn replace_superglobal_value(&mut self, bag: NativeRequestStateBag, value: Value) {
        match value {
            Value::Array(array) => {
                self.superglobals.insert(bag, array);
                self.root_values.remove(&bag);
            }
            value => {
                self.superglobals.remove(&bag);
                self.root_values.insert(bag, ArraySlot::new(value));
            }
        }
    }

    fn replace_superglobal_reference(
        &mut self,
        bag: NativeRequestStateBag,
        reference: PhpReferenceCell,
    ) {
        self.superglobals.remove(&bag);
        self.root_values
            .insert(bag, ArraySlot::from_reference_cell(reference));
    }

    fn prepare_superglobal_keyed_write(
        &mut self,
        bag: NativeRequestStateBag,
    ) -> Result<(), NativeRequestStateOperationStatus> {
        let Some(root_value) = self.root_values.get(&bag) else {
            return Ok(());
        };
        if root_value.reference_cell_id().is_some() {
            return Err(NativeRequestStateOperationStatus::UnsupportedKeyedValue);
        }
        match root_value.value_cloned() {
            Value::Null | Value::Bool(false) => {
                self.root_values.remove(&bag);
                Ok(())
            }
            _ => Err(NativeRequestStateOperationStatus::UnsupportedKeyedValue),
        }
    }

    fn write_superglobal_key(
        &mut self,
        bag: NativeRequestStateBag,
        key: ArrayKey,
        value: Value,
    ) -> NativeRequestStateOperationResult {
        if let Err(status) = self.prepare_superglobal_keyed_write(bag) {
            return NativeRequestStateOperationResult::unsupported(status);
        }
        let is_set = !matches!(value, Value::Null);
        self.superglobals.entry(bag).or_default().insert(key, value);
        NativeRequestStateOperationResult::presence(
            is_set,
            true,
            NativeRequestStateOperationStatus::Ok,
        )
    }

    fn unset_superglobal_key(
        &mut self,
        bag: NativeRequestStateBag,
        key: ArrayKey,
    ) -> NativeRequestStateOperationResult {
        if self.root_values.contains_key(&bag) {
            return NativeRequestStateOperationResult::unsupported(
                NativeRequestStateOperationStatus::UnsupportedKeyedValue,
            );
        }
        if let Some(values) = self.superglobals.get_mut(&bag) {
            values.remove(key);
        }

        NativeRequestStateOperationResult::presence(
            false,
            false,
            NativeRequestStateOperationStatus::Ok,
        )
    }

    fn write_superglobal_path(
        &mut self,
        bag: NativeRequestStateBag,
        keys: &[ArrayKey],
        value: Value,
    ) -> NativeRequestStateOperationResult {
        if keys.is_empty() {
            return NativeRequestStateOperationResult::unsupported(
                NativeRequestStateOperationStatus::InvalidAbi,
            );
        }

        if let Err(status) = self.prepare_superglobal_keyed_write(bag) {
            return NativeRequestStateOperationResult::unsupported(status);
        }
        let values = self.superglobals.entry(bag).or_default();
        let status = request_state_write_path_value(values, keys, value)
            .map(|()| NativeRequestStateOperationStatus::Ok)
            .unwrap_or_else(|status| status);
        request_state_path_mutation_result(self, bag, keys, status)
    }

    fn unset_superglobal_path(
        &mut self,
        bag: NativeRequestStateBag,
        keys: &[ArrayKey],
    ) -> NativeRequestStateOperationResult {
        if keys.is_empty() {
            return NativeRequestStateOperationResult::unsupported(
                NativeRequestStateOperationStatus::InvalidAbi,
            );
        }

        if self.root_values.contains_key(&bag) {
            return NativeRequestStateOperationResult::unsupported(
                NativeRequestStateOperationStatus::UnsupportedKeyedValue,
            );
        }
        let status = self
            .superglobals
            .get_mut(&bag)
            .map(|values| request_state_unset_path_value(values, keys))
            .transpose()
            .map(|_| NativeRequestStateOperationStatus::Ok)
            .unwrap_or_else(|status| status);
        request_state_path_mutation_result(self, bag, keys, status)
    }

    fn populate_superglobal_from_symbol_table(
        &mut self,
        bag: NativeRequestStateBag,
        source: &NativeSymbolTable,
    ) -> bool {
        self.root_values.remove(&bag);
        self.superglobals
            .insert(bag, native_symbol_table_snapshot_array(source));
        true
    }

    fn rebuild_request_from_order(&mut self, order: &[u8]) -> bool {
        let mut request = PhpArray::new();
        for bag in request_population_sources(order) {
            let Some(source) = self.superglobals.get(&bag) else {
                continue;
            };
            for entry in source.entries() {
                request.insert(entry.key.clone(), entry.value_cloned());
            }
        }
        self.root_values.remove(&NativeRequestStateBag::Request);
        self.superglobals
            .insert(NativeRequestStateBag::Request, request);
        true
    }
}

fn request_population_sources(order: &[u8]) -> impl Iterator<Item = NativeRequestStateBag> + '_ {
    order.iter().filter_map(|byte| match byte {
        b'G' | b'g' => Some(NativeRequestStateBag::Get),
        b'P' | b'p' => Some(NativeRequestStateBag::Post),
        b'C' | b'c' => Some(NativeRequestStateBag::Cookie),
        _ => None,
    })
}

fn request_population_policy_order<'a>(
    request_order: Option<&'a NativeString>,
    variables_order: Option<&'a NativeString>,
) -> Option<&'a [u8]> {
    request_order
        .filter(|order| !order.bytes.is_empty())
        .or(variables_order)
        .map(|order| order.bytes.as_slice())
}

