/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. The returned value handle owns a clone of the PHP
/// array value; ownership of `handle` remains with the caller.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_from_array(
    handle: NativeArrayHandle,
) -> NativeValueHandle {
    unsafe { handle.as_ref() }
        .map(|array| NativeValueHandle::from_value(Value::Array(array.value.clone())))
        .unwrap_or_else(NativeValueHandle::null)
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. Array values are cloned into a new array handle;
/// ownership of `handle` remains with the caller. Non-array and null handles
/// return a null array handle.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_array_clone(
    handle: NativeValueHandle,
) -> NativeArrayHandle {
    match unsafe { handle.as_ref() } {
        Some(Value::Array(array)) => NativeArrayHandle::from_array(array.clone()),
        Some(_) | None => NativeArrayHandle::null(),
    }
}

/// # Safety
///
/// `handle` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. The returned handle owns a clone of the value. Null
/// handles clone to null.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_clone(handle: NativeValueHandle) -> NativeValueHandle {
    unsafe { handle.as_ref() }
        .cloned()
        .map(NativeValueHandle::from_value)
        .unwrap_or_else(NativeValueHandle::null)
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_len(handle: NativeArrayHandle) -> usize {
    unsafe { handle.as_ref() }
        .map(|array| array.value.len())
        .unwrap_or(0)
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_append_scalar(
    mut handle: NativeArrayHandle,
    value: NativeScalarValue,
) -> bool {
    let Some(array) = (unsafe { handle.as_mut() }) else {
        return false;
    };

    array.value.append(value.to_value()).is_ok()
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. `value` must be null or a value handle previously
/// returned by the runtime ABI and not yet freed. The appended array slot owns a
/// clone of the value; ownership of `value` remains with the caller.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_append_value(
    handle: NativeArrayHandle,
    value: NativeValueHandle,
) -> bool {
    unsafe { phpc_native_array_append_value_with_diagnostic(handle, value, ptr::null_mut()) }
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. `value` must be null or a value handle previously
/// returned by the runtime ABI and not yet freed. The appended array slot owns a
/// clone of the value; ownership of `value` remains with the caller. On failure
/// the helper stores a diagnostic handle that the caller owns and must release
/// with `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_append_value_with_diagnostic(
    mut handle: NativeArrayHandle,
    value: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    if !diagnostic.is_null() {
        unsafe { *diagnostic = NativeDiagnosticHandle::null() };
    }

    let Some(array) = (unsafe { handle.as_mut() }) else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    RuntimeError::invalid_array_access(
                        "native array append failed: array handle is null",
                    )
                    .message(),
                )
            };
        }
        return false;
    };

    let Some(value) = (unsafe { value.as_ref() }) else {
        if !diagnostic.is_null() {
            unsafe {
                *diagnostic = NativeDiagnosticHandle::from_message(
                    RuntimeError::invalid_array_access(
                        "native array append failed: value handle is null",
                    )
                    .message(),
                )
            };
        }
        return false;
    };

    match array.value.append(value.clone()) {
        Ok(_) => true,
        Err(error) => {
            if !diagnostic.is_null() {
                unsafe { *diagnostic = NativeDiagnosticHandle::from_message(error.message()) };
            }
            false
        }
    }
}

/// # Safety
///
/// `value` must be null or a value handle previously returned by the runtime
/// ABI and not yet freed. The returned key materialization result must be
/// released with `phpc_native_array_key_materialization_result_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_value_to_array_key(
    value: NativeValueHandle,
) -> NativeArrayKeyMaterializationResult {
    let Some(value) = (unsafe { value.as_ref() }) else {
        return NativeArrayKeyMaterializationResult::failure(RuntimeError::invalid_array_key(
            "native array key materialization failed: value handle is null",
        ));
    };

    native_array_key_from_runtime_value(value)
        .map(NativeArrayKeyMaterializationResult::from_array_key)
        .unwrap_or_else(NativeArrayKeyMaterializationResult::failure)
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. `key` must be a result returned by
/// `phpc_native_value_to_array_key`. `value` must be null or a value handle
/// previously returned by the runtime ABI and not yet freed. The inserted array
/// slot owns a clone of the value; ownership of `key` and `value` remains with
/// the caller. On failure the helper stores a diagnostic handle that the caller
/// owns and must release with `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_insert_key_value_with_diagnostic(
    mut handle: NativeArrayHandle,
    key: NativeArrayKeyMaterializationResult,
    value: NativeValueHandle,
    diagnostic: *mut NativeDiagnosticHandle,
) -> bool {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    let Some(array) = (unsafe { handle.as_mut() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                RuntimeError::invalid_array_access(
                    "native array keyed insert failed: array handle is null",
                )
                .message(),
            )
        };
        return false;
    };

    let Some(value) = (unsafe { value.as_ref() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                RuntimeError::invalid_array_access(
                    "native array keyed insert failed: value handle is null",
                )
                .message(),
            )
        };
        return false;
    };

    match unsafe { native_array_key_materialization_to_array_key(&key) } {
        Ok(key) => {
            array.value.insert(key, value.clone());
            true
        }
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            false
        }
    }
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. The returned value handle owns a clone of the indexed
/// array slot, or is null when the array handle is null or the key is missing.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_read_int(
    handle: NativeArrayHandle,
    key: i64,
) -> NativeValueHandle {
    unsafe { handle.as_ref() }
        .and_then(|array| array.value.get_cloned(ArrayKey::Int(key)))
        .map(NativeValueHandle::from_value)
        .unwrap_or_else(NativeValueHandle::null)
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. `key` must be a result returned by
/// `phpc_native_value_to_array_key`. The returned value handle owns a clone of
/// the indexed array slot. Null handles, invalid keys, and missing keys return
/// a null value handle and store a diagnostic when `diagnostic` is non-null;
/// the caller owns that diagnostic and must release it with
/// `phpc_native_diagnostic_free`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_read_key_with_diagnostic(
    handle: NativeArrayHandle,
    key: NativeArrayKeyMaterializationResult,
    diagnostic: *mut NativeDiagnosticHandle,
) -> NativeValueHandle {
    unsafe { native_clear_diagnostic_slot(diagnostic) };

    let Some(array) = (unsafe { handle.as_ref() }) else {
        unsafe {
            native_store_diagnostic_message(
                diagnostic,
                RuntimeError::invalid_array_access(
                    "native array read failed: array handle is null",
                )
                .message(),
            )
        };
        return NativeValueHandle::null();
    };

    match unsafe { native_array_key_materialization_to_array_key(&key) } {
        Ok(key) => array
            .value
            .get_cloned(key.clone())
            .map(NativeValueHandle::from_value)
            .unwrap_or_else(|| {
                unsafe {
                    native_store_diagnostic_message(
                        diagnostic,
                        RuntimeError::undefined_array_key(key.diagnostic_key()).message(),
                    )
                };
                NativeValueHandle::null()
            }),
        Err(error) => {
            unsafe { native_store_diagnostic_message(diagnostic, error.message()) };
            NativeValueHandle::null()
        }
    }
}

/// # Safety
///
/// `handle` must be null or an array handle previously returned by the runtime
/// ABI and not yet freed. The returned snapshot owns clones of the source
/// array's ordered keys and current entry values, and must be freed
/// independently with `phpc_native_array_entry_snapshot_free`. Ownership of
/// `handle` remains with the caller. Null handles return a null snapshot.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_entry_snapshot(
    handle: NativeArrayHandle,
) -> NativeArrayEntrySnapshotHandle {
    unsafe { handle.as_ref() }
        .map(|array| {
            NativeArrayEntrySnapshotHandle::from_entries(
                array
                    .value
                    .entries()
                    .iter()
                    .map(|entry| NativeArrayEntrySnapshotEntry {
                        key: entry.key.clone(),
                        value: entry.value_cloned(),
                    })
                    .collect(),
            )
        })
        .unwrap_or_else(NativeArrayEntrySnapshotHandle::null)
}

#[no_mangle]
pub extern "C" fn phpc_native_array_entry_snapshot_is_null(
    handle: NativeArrayEntrySnapshotHandle,
) -> bool {
    handle.is_null()
}

/// # Safety
///
/// `handle` must be null or an entry snapshot handle previously returned by the
/// runtime ABI and not yet freed. Null snapshots return 0.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_entry_snapshot_len(
    handle: NativeArrayEntrySnapshotHandle,
) -> usize {
    unsafe { handle.as_ref() }
        .map(|snapshot| snapshot.entries.len())
        .unwrap_or(0)
}

/// # Safety
///
/// `handle` must be null or an entry snapshot handle previously returned by the
/// runtime ABI and not yet freed. Invalid indexes and null snapshots return
/// `NativeArrayKeyTag::Invalid`.
#[no_mangle]
pub unsafe extern "C" fn phpc_native_array_entry_snapshot_key_at(
    handle: NativeArrayEntrySnapshotHandle,
    index: usize,
) -> NativeArrayKeyMetadata {
    let Some(entry) = (unsafe { handle.as_ref() }).and_then(|snapshot| snapshot.entries.get(index))
    else {
        return NativeArrayKeyMetadata::invalid();
    };

    native_array_key_metadata(&entry.key)
}

/// # Safety
///
/// `handle` must be null or an entry snapshot handle previously returned by the
/// runtime ABI and not yet freed. The returned string handle owns a clone of
