pub extern "C" fn phpc_native_reference_compare(
    _left: NativeReferenceHandle,
    op: u8,
    _right: NativeReferenceHandle,
) -> NativeComparisonResult {
    native_handle_comparison_blocker(op, ComparisonBlocker::ReferenceDereference)
}

