    fn assert_native_comparison_ok(label: &str, result: NativeComparisonResult, expected: bool) {
        assert_eq!(
            phpc_native_comparison_result_status(result),
            NativeComparisonStatus::Ok as u8,
            "{label}"
        );
        assert_eq!(
            phpc_native_comparison_result_value(result),
            u8::from(expected),
            "{label}"
        );
        assert!(
            phpc_native_comparison_result_diagnostic(result).is_null(),
            "{label}"
        );
        unsafe { phpc_native_comparison_result_free(result) };
    }

    fn assert_native_comparison_blocked(
        label: &str,
        result: NativeComparisonResult,
        expected_message_part: &str,
    ) {
        assert_eq!(
            phpc_native_comparison_result_status(result),
            NativeComparisonStatus::Blocked as u8,
            "{label}"
        );
        assert_eq!(phpc_native_comparison_result_value(result), 0, "{label}");

        let diagnostic = phpc_native_comparison_result_diagnostic(result);
        assert!(!diagnostic.is_null(), "{label}");
        let message = native_diagnostic_message_for_test(diagnostic);
        assert!(
            message.contains(expected_message_part),
            "{label}: {message:?} did not contain {expected_message_part:?}"
        );

        unsafe { phpc_native_comparison_result_free(result) };
    }

    fn compare_native_values_for_test(
        left: Value,
        op: NativeComparisonOp,
        right: Value,
    ) -> NativeComparisonResult {
        let left = NativeValueHandle::from_value(left);
        let right = NativeValueHandle::from_value(right);
        let result = unsafe { phpc_native_value_compare(left, op as u8, right) };
        unsafe { phpc_native_value_free(left) };
        if left.ptr != right.ptr {
            unsafe { phpc_native_value_free(right) };
        }
        result
    }

    #[test]
    fn native_value_operation_results_carry_unary_binary_values_and_blockers() {
        let int_value = phpc_native_value_from_scalar(phpc_native_int(7));
        let string_number = NativeValueHandle::from_value(Value::String("5".to_string()));
        let divisor = phpc_native_value_from_scalar(phpc_native_int(2));
        let suffix = NativeValueHandle::from_value(Value::String("x".to_string()));

        let negated =
            unsafe { phpc_native_value_unary_result(int_value, NATIVE_VALUE_UNARY_NEGATE) };
        assert!(negated.succeeded());
        assert_eq!(native_value_echo_bytes_for_test(negated.value), b"-7");
        unsafe { phpc_native_value_operation_result_free(negated) };

        let string_negated =
            unsafe { phpc_native_value_unary_result(string_number, NATIVE_VALUE_UNARY_NEGATE) };
        assert!(string_negated.succeeded());
        assert_eq!(
            native_value_echo_bytes_for_test(string_negated.value),
            b"-5"
        );
        unsafe { phpc_native_value_operation_result_free(string_negated) };

        let added = unsafe {
            phpc_native_value_binary_result(int_value, NATIVE_VALUE_BINARY_ADD, string_number)
        };
        assert!(added.succeeded());
        assert_eq!(native_value_echo_bytes_for_test(added.value), b"12");
        unsafe { phpc_native_value_operation_result_free(added) };

        let divided =
            unsafe { phpc_native_value_binary_result(int_value, NATIVE_VALUE_BINARY_DIV, divisor) };
        assert!(divided.succeeded());
        assert_eq!(native_value_echo_bytes_for_test(divided.value), b"3.5");
        unsafe { phpc_native_value_operation_result_free(divided) };

        let concatenated = unsafe {
            phpc_native_value_binary_result(string_number, NATIVE_VALUE_BINARY_CONCAT, suffix)
        };
        assert!(concatenated.succeeded());
        assert_eq!(native_value_echo_bytes_for_test(concatenated.value), b"5x");
        unsafe { phpc_native_value_operation_result_free(concatenated) };

        let shifted = unsafe {
            phpc_native_value_binary_result(int_value, NATIVE_VALUE_BINARY_SHIFT_LEFT, divisor)
        };
        assert!(shifted.succeeded());
        assert_eq!(native_value_echo_bytes_for_test(shifted.value), b"28");
        unsafe { phpc_native_value_operation_result_free(shifted) };

        let null_added = unsafe {
            phpc_native_value_binary_result(
                NativeValueHandle::null(),
                NATIVE_VALUE_BINARY_ADD,
                int_value,
            )
        };
        assert!(null_added.succeeded());
        assert_eq!(native_value_echo_bytes_for_test(null_added.value), b"7");
        unsafe { phpc_native_value_operation_result_free(null_added) };

        let array_value = NativeValueHandle::from_value(Value::Array(PhpArray::new()));
        let array_blocked = unsafe {
            phpc_native_value_binary_result(array_value, NATIVE_VALUE_BINARY_ADD, int_value)
        };
        assert_eq!(array_blocked.tag, NativeValueOperationResultTag::Error);
        assert!(native_diagnostic_message_for_test(array_blocked.diagnostic)
            .contains("value-operation boundary"));
        unsafe { phpc_native_value_operation_result_free(array_blocked) };

        let resource_value = NativeValueHandle::from_value(Value::Resource(9));
        let resource_blocked = unsafe {
            phpc_native_value_unary_result(resource_value, NATIVE_VALUE_UNARY_BITWISE_NOT)
        };
        assert_eq!(resource_blocked.tag, NativeValueOperationResultTag::Error);
        assert!(
            native_diagnostic_message_for_test(resource_blocked.diagnostic).contains("resources")
        );
        unsafe { phpc_native_value_operation_result_free(resource_blocked) };

        let bad_op = unsafe { phpc_native_value_binary_result(int_value, 255, divisor) };
        assert_eq!(bad_op.tag, NativeValueOperationResultTag::Error);
        assert_eq!(
            native_diagnostic_message_for_test(bad_op.diagnostic),
            "native value binary operation tag is not supported"
        );
        unsafe { phpc_native_value_operation_result_free(bad_op) };

        unsafe { phpc_native_value_free(resource_value) };
        unsafe { phpc_native_value_free(array_value) };
        unsafe { phpc_native_value_free(suffix) };
        unsafe { phpc_native_value_free(divisor) };
        unsafe { phpc_native_value_free(string_number) };
        unsafe { phpc_native_value_free(int_value) };
    }

    #[test]
    fn native_value_bitwise_operation_reuses_string_and_int_boundaries() {
        fn bitwise_result(
            subject: NativeValueHandle,
            operand: NativeValueHandle,
            operation: u8,
        ) -> Result<NativeValueHandle, String> {
            let mut diagnostic = NativeDiagnosticHandle::null();
            let result = unsafe {
                phpc_native_value_bitwise_operation_with_diagnostic(
                    subject,
                    operand,
                    operation,
                    &mut diagnostic,
                )
            };
            if diagnostic.is_null() {
                assert!(!result.is_null());
                Ok(result)
            } else {
                let message = native_diagnostic_message_for_test(diagnostic);
                unsafe { phpc_native_diagnostic_free(diagnostic) };
                assert!(result.is_null());
                Err(message)
            }
        }

        let left = NativeValueHandle::from_value(Value::String("B".to_string()));
        let right = NativeValueHandle::from_value(Value::String("A".to_string()));
        let zero_byte = NativeValueHandle::from_value(Value::String("\0".to_string()));

        let and_value =
            bitwise_result(left, right, NATIVE_VALUE_BITWISE_AND).expect("string & succeeds");
        assert_eq!(native_value_echo_bytes_for_test(and_value), b"@");
        unsafe { phpc_native_value_free(and_value) };

        let or_value =
            bitwise_result(right, zero_byte, NATIVE_VALUE_BITWISE_OR).expect("string | succeeds");
        assert_eq!(native_value_echo_bytes_for_test(or_value), b"A");
        unsafe { phpc_native_value_free(or_value) };

        let xor_value =
            bitwise_result(right, zero_byte, NATIVE_VALUE_BITWISE_XOR).expect("string ^ succeeds");
        assert_eq!(native_value_echo_bytes_for_test(xor_value), b"A");
        unsafe { phpc_native_value_free(xor_value) };

        let int_subject = NativeValueHandle::from_value(Value::Int(8));
        let shift_count = NativeValueHandle::from_value(Value::String("1".to_string()));
        let shifted = bitwise_result(int_subject, shift_count, NATIVE_VALUE_BITWISE_SHIFT_LEFT)
            .expect("shift through string count succeeds");
        assert_eq!(native_value_echo_bytes_for_test(shifted), b"16");
        unsafe { phpc_native_value_free(shifted) };

        let not_subject = NativeValueHandle::from_value(Value::Int(5));
        let not_value = bitwise_result(
            not_subject,
            NativeValueHandle::null(),
            NATIVE_VALUE_BITWISE_NOT,
        )
        .expect("integer ~ succeeds");
        assert_eq!(native_value_echo_bytes_for_test(not_value), b"-6");
        unsafe { phpc_native_value_free(not_value) };

        let array_subject = NativeValueHandle::from_value(Value::Array(PhpArray::new()));
        let int_operand = NativeValueHandle::from_value(Value::Int(1));
        let error = bitwise_result(array_subject, int_operand, NATIVE_VALUE_BITWISE_AND)
            .expect_err("arrays remain blocked at the shared bitwise boundary");
        assert!(
            error.contains("arrays cannot be used with bitwise operators"),
            "{error}"
        );

        let invalid_tag = bitwise_result(not_subject, int_operand, 255)
            .expect_err("invalid operation tags stay diagnostic-bearing");
        assert!(
            invalid_tag.contains("unsupported operation tag"),
            "{invalid_tag}"
        );

        unsafe { phpc_native_value_free(int_operand) };
        unsafe { phpc_native_value_free(array_subject) };
        unsafe { phpc_native_value_free(not_subject) };
        unsafe { phpc_native_value_free(shift_count) };
        unsafe { phpc_native_value_free(int_subject) };
        unsafe { phpc_native_value_free(zero_byte) };
        unsafe { phpc_native_value_free(right) };
        unsafe { phpc_native_value_free(left) };
    }

    #[test]
    fn native_value_operation_results_cover_compare_cast_and_type_names() {
        let int_value = phpc_native_value_from_scalar(phpc_native_int(7));
        let numeric_string = NativeValueHandle::from_value(Value::String("7".to_string()));
        let smaller_value = phpc_native_value_from_scalar(phpc_native_int(3));
        let string_float = NativeValueHandle::from_value(Value::String("3.5".to_string()));
        let string_zero = NativeValueHandle::from_value(Value::String("0".to_string()));
        let array_value = NativeValueHandle::from_value(Value::Array(PhpArray::new()));
        let resource_value = NativeValueHandle::from_value(Value::Resource(9));

        let equal = unsafe {
            phpc_native_value_compare_result(int_value, NATIVE_VALUE_COMPARISON_EQ, numeric_string)
        };
        assert!(equal.succeeded());
        assert_eq!(native_value_echo_bytes_for_test(equal.value), b"1");
        unsafe { phpc_native_value_operation_result_free(equal) };

        let greater = unsafe {
            phpc_native_value_compare_result(int_value, NATIVE_VALUE_COMPARISON_GT, smaller_value)
        };
        assert!(greater.succeeded());
        assert_eq!(native_value_echo_bytes_for_test(greater.value), b"1");
        unsafe { phpc_native_value_operation_result_free(greater) };

        let int_cast =
            unsafe { phpc_native_value_cast_result(string_float, NATIVE_VALUE_CAST_INT) };
        assert!(int_cast.succeeded());
        assert_eq!(native_value_echo_bytes_for_test(int_cast.value), b"3");
        unsafe { phpc_native_value_operation_result_free(int_cast) };

        let float_cast =
            unsafe { phpc_native_value_cast_result(string_float, NATIVE_VALUE_CAST_FLOAT) };
        assert!(float_cast.succeeded());
        assert_eq!(native_value_echo_bytes_for_test(float_cast.value), b"3.5");
        unsafe { phpc_native_value_operation_result_free(float_cast) };

        let string_cast =
            unsafe { phpc_native_value_cast_result(int_value, NATIVE_VALUE_CAST_STRING) };
        assert!(string_cast.succeeded());
        assert_eq!(native_value_echo_bytes_for_test(string_cast.value), b"7");
        unsafe { phpc_native_value_operation_result_free(string_cast) };

        let false_cast =
            unsafe { phpc_native_value_cast_result(string_zero, NATIVE_VALUE_CAST_BOOL) };
        assert!(false_cast.succeeded());
        assert_eq!(native_value_echo_bytes_for_test(false_cast.value), b"");
        unsafe { phpc_native_value_operation_result_free(false_cast) };

        let null_array_cast = unsafe {
            phpc_native_value_cast_result(NativeValueHandle::null(), NATIVE_VALUE_CAST_ARRAY)
        };
        assert!(null_array_cast.succeeded());
        assert!(matches!(
            unsafe { null_array_cast.value.as_ref() },
            Some(Value::Array(array)) if array.is_empty()
        ));
        unsafe { phpc_native_value_operation_result_free(null_array_cast) };

        let gettype_null = unsafe {
            phpc_native_value_type_name_result(
                NativeValueHandle::null(),
                NATIVE_VALUE_TYPE_NAME_GETTYPE,
            )
        };
        assert!(gettype_null.succeeded());
        assert_eq!(
            native_value_echo_bytes_for_test(gettype_null.value),
            b"NULL"
        );
        unsafe { phpc_native_value_operation_result_free(gettype_null) };

        let debug_array = unsafe {
            phpc_native_value_type_name_result(array_value, NATIVE_VALUE_TYPE_NAME_DEBUG)
        };
        assert!(debug_array.succeeded());
        assert_eq!(
            native_value_echo_bytes_for_test(debug_array.value),
            b"array"
        );
        unsafe { phpc_native_value_operation_result_free(debug_array) };

        let array_comparison = unsafe {
            phpc_native_value_compare_result(array_value, NATIVE_VALUE_COMPARISON_EQ, int_value)
        };
        assert_eq!(array_comparison.tag, NativeValueOperationResultTag::Error);
        assert!(
            native_diagnostic_message_for_test(array_comparison.diagnostic)
                .contains("value-operation comparison boundary")
        );
        unsafe { phpc_native_value_operation_result_free(array_comparison) };

        let resource_cast =
            unsafe { phpc_native_value_cast_result(resource_value, NATIVE_VALUE_CAST_FLOAT) };
        assert_eq!(resource_cast.tag, NativeValueOperationResultTag::Error);
        assert!(native_diagnostic_message_for_test(resource_cast.diagnostic).contains("resource"));
        unsafe { phpc_native_value_operation_result_free(resource_cast) };

        let resource_type = unsafe {
            phpc_native_value_type_name_result(resource_value, NATIVE_VALUE_TYPE_NAME_DEBUG)
        };
        assert_eq!(resource_type.tag, NativeValueOperationResultTag::Error);
        assert!(native_diagnostic_message_for_test(resource_type.diagnostic)
            .contains("resource debug names"));
        unsafe { phpc_native_value_operation_result_free(resource_type) };

        let bad_comparison = unsafe { phpc_native_value_compare_result(int_value, 255, int_value) };
        assert_eq!(bad_comparison.tag, NativeValueOperationResultTag::Error);
        assert_eq!(
            native_diagnostic_message_for_test(bad_comparison.diagnostic),
            "native value comparison operation tag is not supported"
        );
        unsafe { phpc_native_value_operation_result_free(bad_comparison) };

        let bad_cast = unsafe { phpc_native_value_cast_result(int_value, 255) };
        assert_eq!(bad_cast.tag, NativeValueOperationResultTag::Error);
        assert_eq!(
            native_diagnostic_message_for_test(bad_cast.diagnostic),
            "native value cast operation tag is not supported"
        );
        unsafe { phpc_native_value_operation_result_free(bad_cast) };

        let bad_type_name = unsafe { phpc_native_value_type_name_result(int_value, 255) };
        assert_eq!(bad_type_name.tag, NativeValueOperationResultTag::Error);
        assert_eq!(
            native_diagnostic_message_for_test(bad_type_name.diagnostic),
            "native value type-name operation tag 255 is not supported"
        );
        unsafe { phpc_native_value_operation_result_free(bad_type_name) };

        unsafe { phpc_native_value_free(resource_value) };
        unsafe { phpc_native_value_free(array_value) };
        unsafe { phpc_native_value_free(string_zero) };
        unsafe { phpc_native_value_free(string_float) };
        unsafe { phpc_native_value_free(smaller_value) };
        unsafe { phpc_native_value_free(numeric_string) };
        unsafe { phpc_native_value_free(int_value) };
    }

    #[test]
    fn native_value_type_predicate_classifies_value_families() {
        let bool_value = phpc_native_value_from_scalar(phpc_native_bool(true));
        let int_value = phpc_native_value_from_scalar(phpc_native_int(7));
        let float_value = phpc_native_value_from_scalar(phpc_native_float(2.5));
        let numeric_string = NativeValueHandle::from_value(Value::String("42".to_string()));
        let text_string = NativeValueHandle::from_value(Value::String("forty-two".to_string()));
        let mut array = PhpArray::new();
        array.insert(ArrayKey::Int(0), Value::String("slot".to_string()));
        let array_value = NativeValueHandle::from_value(Value::Array(array));
        let resource_value = NativeValueHandle::from_value(Value::Resource(9));
        let closure_value =
            NativeValueHandle::from_value(Value::Closure(PhpClosure::new(1, false, Vec::new())));

        assert!(unsafe {
            phpc_native_value_type_predicate(NativeValueHandle::null(), NATIVE_VALUE_TYPE_IS_NULL)
        });
        assert!(unsafe { phpc_native_value_type_predicate(bool_value, NATIVE_VALUE_TYPE_IS_BOOL) });
        assert!(unsafe { phpc_native_value_type_predicate(int_value, NATIVE_VALUE_TYPE_IS_INT) });
        assert!(unsafe {
            phpc_native_value_type_predicate(float_value, NATIVE_VALUE_TYPE_IS_FLOAT)
        });
        assert!(unsafe {
            phpc_native_value_type_predicate(numeric_string, NATIVE_VALUE_TYPE_IS_STRING)
        });
        assert!(unsafe {
            phpc_native_value_type_predicate(array_value, NATIVE_VALUE_TYPE_IS_ARRAY)
        });
        assert!(unsafe {
            phpc_native_value_type_predicate(int_value, NATIVE_VALUE_TYPE_IS_SCALAR)
        });
        assert!(unsafe {
            phpc_native_value_type_predicate(numeric_string, NATIVE_VALUE_TYPE_IS_NUMERIC)
        });
        assert!(!unsafe {
            phpc_native_value_type_predicate(text_string, NATIVE_VALUE_TYPE_IS_NUMERIC)
        });
        assert!(unsafe {
            phpc_native_value_type_predicate(array_value, NATIVE_VALUE_TYPE_IS_COUNTABLE)
        });
        assert!(unsafe {
            phpc_native_value_type_predicate(array_value, NATIVE_VALUE_TYPE_IS_ITERABLE)
        });
        assert!(unsafe {
            phpc_native_value_type_predicate(closure_value, NATIVE_VALUE_TYPE_IS_OBJECT)
        });
        assert!(!unsafe {
            phpc_native_value_type_predicate(resource_value, NATIVE_VALUE_TYPE_IS_OBJECT)
        });
        assert!(!unsafe {
            phpc_native_value_type_predicate(int_value, NATIVE_VALUE_TYPE_IS_ARRAY)
        });
        assert!(!unsafe { phpc_native_value_type_predicate(int_value, u8::MAX) });

        unsafe { phpc_native_value_free(closure_value) };
        unsafe { phpc_native_value_free(resource_value) };
        unsafe { phpc_native_value_free(array_value) };
        unsafe { phpc_native_value_free(text_string) };
        unsafe { phpc_native_value_free(numeric_string) };
        unsafe { phpc_native_value_free(float_value) };
        unsafe { phpc_native_value_free(int_value) };
        unsafe { phpc_native_value_free(bool_value) };
    }

    #[test]
    fn native_value_cast_operations_reuse_value_result_boundaries() {
        let numeric = NativeValueHandle::from_value(Value::String(" -12.8 ".to_string()));
        let falsey = NativeValueHandle::from_value(Value::String("0".to_string()));
        let text = NativeValueHandle::from_value(Value::String("A\0B".to_string()));
        let empty_array = NativeValueHandle::from_value(Value::Array(PhpArray::new()));
        let mut nonempty_array = PhpArray::new();
        nonempty_array.append(Value::Int(1)).unwrap();
        let nonempty_array = NativeValueHandle::from_value(Value::Array(nonempty_array));
        let mut diagnostic = NativeDiagnosticHandle::null();

        let string = unsafe {
            phpc_native_value_cast_operation_with_diagnostic(
                text,
                NativeValueCastOperation::String as u8,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert_eq!(native_value_echo_bytes_for_test(string), b"A\0B");

        let integer = unsafe {
            phpc_native_value_cast_operation_with_diagnostic(
                numeric,
                NativeValueCastOperation::Int as u8,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert_eq!(native_value_echo_bytes_for_test(integer), b"-12");

        let float = unsafe {
            phpc_native_value_cast_operation_with_diagnostic(
                numeric,
                NativeValueCastOperation::Float as u8,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert_eq!(native_value_echo_bytes_for_test(float), b"-12.8");

        let boolean = unsafe {
            phpc_native_value_cast_operation_with_diagnostic(
                falsey,
                NativeValueCastOperation::Bool as u8,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert_eq!(native_value_echo_bytes_for_test(boolean), b"");

        let array = unsafe {
            phpc_native_value_cast_operation_with_diagnostic(
                text,
                NativeValueCastOperation::Array as u8,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert!(matches!(
            unsafe { array.as_ref() },
            Some(Value::Array(array)) if array.entries().len() == 1
        ));

        let empty_array_int = unsafe {
            phpc_native_value_cast_operation_with_diagnostic(
                empty_array,
                NativeValueCastOperation::Int as u8,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert_eq!(native_value_echo_bytes_for_test(empty_array_int), b"0");

        let nonempty_array_float = unsafe {
            phpc_native_value_cast_operation_with_diagnostic(
                nonempty_array,
                NativeValueCastOperation::Float as u8,
                &mut diagnostic,
            )
        };
        assert!(diagnostic.is_null());
        assert_eq!(native_value_echo_bytes_for_test(nonempty_array_float), b"1");

        let bad_op =
            unsafe { phpc_native_value_cast_operation_with_diagnostic(text, 255, &mut diagnostic) };
        assert!(bad_op.is_null());
        assert_eq!(
            native_diagnostic_message_for_test(diagnostic),
            "unsupported call native value cast: native value cast operation tag 255 is not supported"
        );

        unsafe { phpc_native_diagnostic_free(diagnostic) };
        unsafe { phpc_native_value_free(nonempty_array_float) };
        unsafe { phpc_native_value_free(empty_array_int) };
        unsafe { phpc_native_value_free(array) };
        unsafe { phpc_native_value_free(boolean) };
        unsafe { phpc_native_value_free(float) };
        unsafe { phpc_native_value_free(integer) };
        unsafe { phpc_native_value_free(string) };
        unsafe { phpc_native_value_free(nonempty_array) };
        unsafe { phpc_native_value_free(empty_array) };
        unsafe { phpc_native_value_free(text) };
        unsafe { phpc_native_value_free(falsey) };
        unsafe { phpc_native_value_free(numeric) };
    }

    #[test]
    fn native_comparison_abi_tags_are_stable() {
        assert_eq!(NativeComparisonStatus::Ok as u8, 0);
        assert_eq!(NativeComparisonStatus::Blocked as u8, 1);
        assert_eq!(NativeComparisonOp::LooseEq as u8, 0);
        assert_eq!(NativeComparisonOp::LooseNe as u8, 1);
        assert_eq!(NativeComparisonOp::LooseLt as u8, 2);
        assert_eq!(NativeComparisonOp::LooseLe as u8, 3);
        assert_eq!(NativeComparisonOp::LooseGt as u8, 4);
        assert_eq!(NativeComparisonOp::LooseGe as u8, 5);
        assert_eq!(NativeComparisonOp::StrictEq as u8, 6);
        assert_eq!(NativeComparisonOp::StrictNe as u8, 7);
    }

    #[test]
    fn comparison_operation_family_classifies_loose_and_strict_ops() {
        for (op, expected_family, expected_loose, expected_identity) in [
            (
                PhpComparisonOp::LooseEq,
                ComparisonOperationFamily::LooseEquality(Comparison::Eq),
                Some(Comparison::Eq),
                None,
            ),
            (
                PhpComparisonOp::LooseNe,
                ComparisonOperationFamily::LooseEquality(Comparison::Ne),
                Some(Comparison::Ne),
                None,
            ),
            (
                PhpComparisonOp::LooseLt,
                ComparisonOperationFamily::LooseOrdering(Comparison::Lt),
                Some(Comparison::Lt),
                None,
            ),
            (
                PhpComparisonOp::LooseLe,
                ComparisonOperationFamily::LooseOrdering(Comparison::Le),
                Some(Comparison::Le),
                None,
            ),
            (
                PhpComparisonOp::LooseGt,
                ComparisonOperationFamily::LooseOrdering(Comparison::Gt),
                Some(Comparison::Gt),
                None,
            ),
            (
                PhpComparisonOp::LooseGe,
                ComparisonOperationFamily::LooseOrdering(Comparison::Ge),
                Some(Comparison::Ge),
                None,
            ),
            (
                PhpComparisonOp::StrictEq,
                ComparisonOperationFamily::StrictIdentity {
                    expected_identical: true,
                },
                None,
                Some(true),
            ),
            (
                PhpComparisonOp::StrictNe,
                ComparisonOperationFamily::StrictIdentity {
                    expected_identical: false,
                },
                None,
                Some(false),
            ),
        ] {
            let family = op.operation_family();

            assert_eq!(family, expected_family, "{op:?}");
            assert_eq!(family.loose_comparison(), expected_loose, "{op:?}");
            assert_eq!(
                family.strict_identity_expectation(),
                expected_identity,
                "{op:?}"
            );
            assert_eq!(
                family.uses_loose_value_semantics(),
                expected_loose.is_some(),
                "{op:?}"
            );
        }
    }

    #[test]
    fn comparison_value_family_drives_loose_blockers_across_operator_families() {
        let mut classes = PhpClassTable::new();
        let class_id = classes.declare_class("Box").unwrap();
        let object = Value::Object(PhpObject::from_class(classes.get(class_id).unwrap()));
        let closure = Value::Closure(PhpClosure::new(17, false, Vec::new()));
        let loose_ops = [
            PhpComparisonOp::LooseEq,
            PhpComparisonOp::LooseNe,
            PhpComparisonOp::LooseLt,
            PhpComparisonOp::LooseLe,
            PhpComparisonOp::LooseGt,
            PhpComparisonOp::LooseGe,
        ];

        for (label, value, family) in [
            (
                "array",
                Value::Array(PhpArray::new()),
                ComparisonValueFamily::Array,
            ),
            ("object", object, ComparisonValueFamily::Object),
            ("closure", closure, ComparisonValueFamily::Object),
            (
                "resource",
                Value::Resource(9),
                ComparisonValueFamily::Resource,
            ),
        ] {
            assert_eq!(ComparisonValueFamily::for_value(&value), family, "{label}");

            for op in loose_ops {
                let operation = op.operation_family();
                let left_blocker = match family {
                    ComparisonValueFamily::Array => ComparisonBlocker::RecursiveArrayComparison {
                        side: ComparisonOperandSide::Left,
                        operation,
                    },
                    _ => ComparisonBlocker::UnsupportedValueFamily {
                        side: ComparisonOperandSide::Left,
                        family,
                        operation,
                    },
                };
                let right_blocker = match family {
                    ComparisonValueFamily::Array => ComparisonBlocker::RecursiveArrayComparison {
                        side: ComparisonOperandSide::Right,
                        operation,
                    },
                    _ => ComparisonBlocker::UnsupportedValueFamily {
                        side: ComparisonOperandSide::Right,
                        family,
                        operation,
                    },
                };

                assert_eq!(
                    comparison_blocker_for_family(&value, &Value::Int(1), operation),
                    Some(left_blocker),
                    "{label} left blocker for {op:?}",
                );
                assert_eq!(
                    comparison_blocker_for_family(
                        &Value::String("1".to_string()),
                        &value,
                        operation
                    ),
                    Some(right_blocker),
                    "{label} right blocker for {op:?}",
                );
                assert_eq!(
                    value
                        .php_compare_checked(&Value::Int(1), op)
                        .unwrap_err()
                        .message(),
                    left_blocker.runtime_error().message(),
                    "{label} runtime blocker for {op:?}",
                );
            }

            for op in [PhpComparisonOp::StrictEq, PhpComparisonOp::StrictNe] {
                assert_eq!(
                    comparison_blocker_for_family(&value, &Value::Int(1), op.operation_family()),
                    None,
                    "{label} strict identity blocker for {op:?}",
                );
                value
                    .php_compare_checked(&Value::Int(1), op)
                    .expect("strict identity should compare without loose blockers");
            }
        }

        for scalar in [
            Value::Null,
            Value::Bool(false),
            Value::Int(1),
            Value::Float(1.5),
            Value::String("10".to_string()),
        ] {
            assert_eq!(
                ComparisonValueFamily::for_value(&scalar),
                ComparisonValueFamily::Scalar
            );
            for op in loose_ops {
                assert_eq!(
                    comparison_blocker_for_family(&scalar, &Value::Int(2), op.operation_family()),
                    None
                );
                scalar
                    .php_compare_checked(&Value::Int(2), op)
                    .expect("scalar loose comparison should remain supported");
            }
        }
    }

    #[test]
    fn native_scalar_comparison_covers_loose_and_strict_ops() {
        for (label, left, op, right, expected) in [
            (
                "int loose less-than",
                phpc_native_int(2),
                NativeComparisonOp::LooseLt,
                phpc_native_int(10),
                true,
            ),
            (
                "float loose greater-equal",
                phpc_native_float(2.5),
                NativeComparisonOp::LooseGe,
                phpc_native_float(3.0),
                false,
            ),
            (
                "bool/null loose equality",
                phpc_native_bool(false),
                NativeComparisonOp::LooseEq,
                phpc_native_null(),
                true,
            ),
            (
                "strict type mismatch",
                phpc_native_int(1),
                NativeComparisonOp::StrictEq,
                phpc_native_float(1.0),
                false,
            ),
            (
                "strict non-identity",
                phpc_native_bool(true),
                NativeComparisonOp::StrictNe,
                phpc_native_int(1),
                true,
            ),
        ] {
            assert_native_comparison_ok(
                label,
                phpc_native_scalar_compare(left, op as u8, right),
                expected,
            );
        }

        assert_native_comparison_blocked(
            "invalid opcode",
            phpc_native_scalar_compare(phpc_native_int(1), 99, phpc_native_int(1)),
            "unsupported comparison opcode 99",
        );
    }

    #[test]
    fn native_value_comparison_covers_value_and_blocker_families() {
        assert_native_comparison_ok(
            "numeric string loose comparison",
            compare_native_values_for_test(
                Value::String("10".to_string()),
                NativeComparisonOp::LooseGt,
                Value::Int(2),
            ),
            true,
        );

        assert_native_comparison_ok(
            "array strict identity",
            compare_native_values_for_test(
                Value::Array(PhpArray::new()),
                NativeComparisonOp::StrictEq,
                Value::Array(PhpArray::new()),
            ),
            true,
        );

        assert_native_comparison_ok(
            "closure strict identity by id",
            compare_native_values_for_test(
                Value::Closure(PhpClosure::new(42, false, Vec::new())),
                NativeComparisonOp::StrictEq,
                Value::Closure(PhpClosure::new(42, false, Vec::new())),
            ),
            true,
        );

        assert_native_comparison_blocked(
            "loose array blocker",
            compare_native_values_for_test(
                Value::Array(PhpArray::new()),
                NativeComparisonOp::LooseEq,
                Value::Int(1),
            ),
            "recursive array comparisons are not implemented",
        );

        assert_native_comparison_blocked(
            "loose closure blocker",
            compare_native_values_for_test(
                Value::Closure(PhpClosure::new(7, false, Vec::new())),
                NativeComparisonOp::LooseEq,
                Value::String("callable".to_string()),
            ),
            "object comparisons are not implemented",
        );

        assert_native_comparison_blocked(
            "loose resource blocker",
            compare_native_values_for_test(
                Value::Resource(3),
                NativeComparisonOp::LooseNe,
                Value::Resource(4),
            ),
            "resource comparisons are not implemented",
        );

        let right = NativeValueHandle::from_value(Value::Int(1));
        let null_left_result = unsafe {
            phpc_native_value_compare(
                NativeValueHandle::null(),
                NativeComparisonOp::LooseEq as u8,
                right,
            )
        };
        unsafe { phpc_native_value_free(right) };
        assert_native_comparison_blocked(
            "null left value handle",
            null_left_result,
            "left value handle is null",
        );
    }

    #[test]
    fn native_value_compare_and_free_consumes_owned_handles_across_result_families() {
        assert_native_comparison_ok(
            "owned loose ordering",
            unsafe {
                phpc_native_value_compare_and_free(
                    NativeValueHandle::from_value(Value::Int(1)),
                    NativeComparisonOp::LooseLt as u8,
                    NativeValueHandle::from_value(Value::Int(2)),
                )
            },
            true,
        );

        let alias = NativeValueHandle::from_value(Value::String("same".to_string()));
        assert_native_comparison_ok(
            "owned strict alias identity",
            unsafe {
                phpc_native_value_compare_and_free(alias, NativeComparisonOp::StrictEq as u8, alias)
            },
            true,
        );

        assert_native_comparison_blocked(
            "owned loose array blocker",
            unsafe {
                phpc_native_value_compare_and_free(
                    NativeValueHandle::from_value(Value::Array(PhpArray::new())),
                    NativeComparisonOp::LooseEq as u8,
                    NativeValueHandle::from_value(Value::Int(1)),
                )
            },
            "recursive array comparisons are not implemented",
        );
    }

    #[test]
    fn native_value_compare_branch_and_free_consumes_owned_results_across_families() {
        for (label, branch, expected) in [
            (
                "owned loose ordering branch",
                unsafe {
                    phpc_native_value_compare_branch_and_free(
                        phpc_native_value_from_scalar(phpc_native_int(2)),
                        NativeComparisonOp::LooseLt as u8,
                        phpc_native_value_from_scalar(phpc_native_int(10)),
                    )
                },
                true,
            ),
            (
                "owned null/bool equality branch",
                unsafe {
                    phpc_native_value_compare_branch_and_free(
                        phpc_native_value_from_scalar(phpc_native_null()),
                        NativeComparisonOp::LooseEq as u8,
                        phpc_native_value_from_scalar(phpc_native_bool(false)),
                    )
                },
                true,
            ),
            (
                "owned strict non-identity branch",
                unsafe {
                    phpc_native_value_compare_branch_and_free(
                        phpc_native_value_from_scalar(phpc_native_bool(true)),
                        NativeComparisonOp::StrictNe as u8,
                        phpc_native_value_from_scalar(phpc_native_int(1)),
                    )
                },
                true,
            ),
            (
                "owned aliased handle branch",
                {
                    let alias = phpc_native_value_from_scalar(phpc_native_int(7));
                    unsafe {
                        phpc_native_value_compare_branch_and_free(
                            alias,
                            NativeComparisonOp::StrictEq as u8,
                            alias,
                        )
                    }
                },
                true,
            ),
        ] {
            assert_eq!(branch.status(), NativeComparisonStatus::Ok as u8, "{label}");
            assert_eq!(branch.value(), expected, "{label}");
            assert_eq!(branch.diagnostic_len(), 0, "{label}");
        }

        for (label, branch) in [
            ("owned branch array blocker", unsafe {
                phpc_native_value_compare_branch_and_free(
                    NativeValueHandle::from_value(Value::Array(PhpArray::new())),
                    NativeComparisonOp::LooseEq as u8,
                    phpc_native_value_from_scalar(phpc_native_int(1)),
                )
            }),
            ("owned branch invalid opcode blocker", unsafe {
                phpc_native_value_compare_branch_and_free(
                    phpc_native_value_from_scalar(phpc_native_int(1)),
                    99,
                    phpc_native_value_from_scalar(phpc_native_int(1)),
                )
            }),
            ("owned branch null-handle blocker", unsafe {
                phpc_native_value_compare_branch_and_free(
                    NativeValueHandle::null(),
                    NativeComparisonOp::LooseEq as u8,
                    phpc_native_value_from_scalar(phpc_native_int(1)),
                )
            }),
        ] {
            assert_eq!(
                branch.status(),
                NativeComparisonStatus::Blocked as u8,
                "{label}"
            );
            assert!(!branch.value(), "{label}");
            assert!(branch.diagnostic_len() > 0, "{label}");
        }
    }

    #[test]
    fn native_comparison_branch_result_accessors_cover_owned_success_and_blockers() {
        let success = unsafe {
            phpc_native_value_compare_branch_and_free(
                phpc_native_value_from_scalar(phpc_native_int(2)),
                NativeComparisonOp::LooseLt as u8,
                phpc_native_value_from_scalar(phpc_native_int(10)),
            )
        };
        assert_eq!(
            phpc_native_comparison_branch_result_status(success),
            NativeComparisonStatus::Ok as u8
        );
        assert_eq!(phpc_native_comparison_branch_result_value(success), 1);
        assert!(phpc_native_comparison_branch_result_is_true(success));
        assert_eq!(
            phpc_native_comparison_branch_result_diagnostic_len(success),
            0
        );
        assert_eq!(phpc_native_comparison_branch_result_exit_code(success), 0);

        let false_success = unsafe {
            phpc_native_value_compare_branch_and_free(
                phpc_native_value_from_scalar(phpc_native_int(2)),
                NativeComparisonOp::LooseGt as u8,
                phpc_native_value_from_scalar(phpc_native_int(10)),
            )
        };
        assert_eq!(
            phpc_native_comparison_branch_result_status(false_success),
            NativeComparisonStatus::Ok as u8
        );
        assert_eq!(phpc_native_comparison_branch_result_value(false_success), 0);
        assert!(!phpc_native_comparison_branch_result_is_true(false_success));
        assert_eq!(
            phpc_native_comparison_branch_result_diagnostic_len(false_success),
            0
        );
        assert_eq!(
            phpc_native_comparison_branch_result_exit_code(false_success),
            0
        );

        let blocked = unsafe {
            phpc_native_value_compare_branch_and_free(
                NativeValueHandle::from_value(Value::Array(PhpArray::new())),
                NativeComparisonOp::LooseEq as u8,
                phpc_native_value_from_scalar(phpc_native_int(1)),
            )
        };
        assert_eq!(
            phpc_native_comparison_branch_result_status(blocked),
            NativeComparisonStatus::Blocked as u8
        );
        assert_eq!(phpc_native_comparison_branch_result_value(blocked), 0);
        assert!(!phpc_native_comparison_branch_result_is_true(blocked));
        assert!(phpc_native_comparison_branch_result_diagnostic_len(blocked) > 0);
        assert_eq!(phpc_native_comparison_branch_result_exit_code(blocked), 1);

        let malformed = NativeComparisonBranchResult {
            status: 99,
            value: 7,
            diagnostic_len: 11,
        };
        assert_eq!(
            phpc_native_comparison_branch_result_status(malformed),
            NativeComparisonStatus::Blocked as u8
        );
        assert_eq!(phpc_native_comparison_branch_result_value(malformed), 0);
        assert!(!phpc_native_comparison_branch_result_is_true(malformed));
        assert_eq!(
            phpc_native_comparison_branch_result_diagnostic_len(malformed),
            11
        );
        assert_eq!(phpc_native_comparison_branch_result_exit_code(malformed), 1);
    }

    #[test]
    fn native_comparison_branch_decision_consumes_branch_results_across_families() {
        let scalar_order = unsafe {
            phpc_native_value_compare_branch_and_free(
                phpc_native_value_from_scalar(phpc_native_int(2)),
                NativeComparisonOp::LooseLt as u8,
                phpc_native_value_from_scalar(phpc_native_int(10)),
            )
        };
        let scalar_equality = unsafe {
            phpc_native_value_compare_branch_and_free(
                phpc_native_value_from_scalar(phpc_native_null()),
                NativeComparisonOp::LooseEq as u8,
                phpc_native_value_from_scalar(phpc_native_bool(false)),
            )
        };
        let scalar_identity = unsafe {
            phpc_native_value_compare_branch_and_free(
                phpc_native_value_from_scalar(phpc_native_int(2)),
                NativeComparisonOp::StrictEq as u8,
                phpc_native_value_from_scalar(phpc_native_int(2)),
            )
        };
        let value_array_blocker = unsafe {
            phpc_native_value_compare_branch_and_free(
                NativeValueHandle::from_value(Value::Array(PhpArray::new())),
                NativeComparisonOp::LooseEq as u8,
                phpc_native_value_from_scalar(phpc_native_int(1)),
            )
        };
        let array_loose_blocker = unsafe {
            phpc_native_array_compare_branch_and_free(
                phpc_native_array_empty(),
                NativeComparisonOp::LooseEq as u8,
                phpc_native_array_empty(),
            )
        };
        let malformed = NativeComparisonBranchResult {
            status: 99,
            value: 7,
            diagnostic_len: 11,
        };

        for (label, branch, expected_true, expected_exit) in [
            ("loose ordering branch decision", scalar_order, true, 0),
            ("loose equality branch decision", scalar_equality, true, 0),
            ("strict identity branch decision", scalar_identity, true, 0),
            (
                "value-array blocker branch decision",
                value_array_blocker,
                false,
                1,
            ),
            (
                "array blocker branch decision",
                array_loose_blocker,
                false,
                1,
            ),
            ("malformed branch decision", malformed, false, 1),
        ] {
            let decision = phpc_native_comparison_branch_decision_from_result(branch);
            let expected_status = if expected_exit == 0 {
                NativeComparisonStatus::Ok as u8
            } else {
                NativeComparisonStatus::Blocked as u8
            };
            let expected_blocked = expected_status == NativeComparisonStatus::Blocked as u8;
            assert_eq!(
                phpc_native_comparison_branch_decision_status(decision),
                expected_status,
                "{label}"
            );
            assert_eq!(
                phpc_native_comparison_branch_decision_is_blocked(decision),
                expected_blocked,
                "{label}"
            );
            assert_eq!(
                phpc_native_comparison_branch_decision_exit_code(decision),
                expected_exit,
                "{label}"
            );
            assert_eq!(
                phpc_native_comparison_branch_decision_abort_code(decision),
                expected_exit,
                "{label}"
            );
            assert_eq!(
                phpc_native_comparison_branch_decision_is_true(decision),
                expected_true,
                "{label}"
            );
        }

        let malformed_decision = NativeComparisonBranchDecision {
            exit_code: 7,
            value: 1,
        };
        assert!(phpc_native_comparison_branch_decision_is_blocked(
            malformed_decision
        ));
        assert_eq!(
            phpc_native_comparison_branch_decision_abort_code(malformed_decision),
            7
        );
        assert!(!phpc_native_comparison_branch_decision_is_true(
            malformed_decision
        ));
    }

    #[test]
    fn native_comparison_outcome_centralizes_result_and_branch_conversion() {
        let cases = vec![
            (
                "scalar comparison success",
                Ok(ComparisonEvaluation::Value(true)),
                NativeComparisonStatus::Ok as u8,
                true,
                0,
            ),
            (
                "strict identity false success",
                Ok(ComparisonEvaluation::Value(false)),
                NativeComparisonStatus::Ok as u8,
                false,
                0,
            ),
            (
                "array semantic blocker",
                Ok(ComparisonEvaluation::Blocked(
                    ComparisonBlocker::UnsupportedValueFamily {
                        side: ComparisonOperandSide::Left,
                        family: ComparisonValueFamily::Array,
                        operation: PhpComparisonOp::LooseEq.operation_family(),
                    },
                )),
                NativeComparisonStatus::Blocked as u8,
                false,
                1,
            ),
            (
                "resource semantic blocker",
                Ok(ComparisonEvaluation::Blocked(
                    ComparisonBlocker::UnsupportedValueFamily {
                        side: ComparisonOperandSide::Right,
                        family: ComparisonValueFamily::Resource,
                        operation: PhpComparisonOp::LooseLt.operation_family(),
                    },
                )),
                NativeComparisonStatus::Blocked as u8,
                false,
                1,
            ),
            (
                "runtime error blocker",
                Err(RuntimeError::unsupported_comparison(
                    "synthetic comparison conversion failure",
                )),
                NativeComparisonStatus::Blocked as u8,
                false,
                1,
            ),
        ];

        for (label, evaluation, expected_status, expected_value, expected_exit_code) in cases {
            let result =
                NativeComparisonOutcome::from_evaluation(evaluation.clone()).into_native_result();
            assert_eq!(result.status(), expected_status, "{label}");
            assert_eq!(result.value(), expected_value, "{label}");
            assert_eq!(result.exit_code(), expected_exit_code, "{label}");
            assert_eq!(
                result.diagnostic().is_null(),
                expected_status == NativeComparisonStatus::Ok as u8,
                "{label}"
            );
            unsafe { phpc_native_comparison_result_free(result) };

            let branch = NativeComparisonOutcome::from_evaluation(evaluation).into_branch_result();
            assert_eq!(branch.status(), expected_status, "{label}");
            assert_eq!(branch.value(), expected_value, "{label}");
            assert_eq!(branch.exit_code(), expected_exit_code, "{label}");
            assert_eq!(
                branch.diagnostic_len() == 0,
                expected_status == NativeComparisonStatus::Ok as u8,
                "{label}"
            );
        }
    }

    #[test]
    fn native_comparison_result_exit_code_matches_branch_contract_across_families() {
        for (label, result, expected_exit_code) in [
            (
                "scalar loose ordering success",
                phpc_native_scalar_compare(
                    phpc_native_int(2),
                    NativeComparisonOp::LooseLt as u8,
                    phpc_native_int(10),
                ),
                0,
            ),
            (
                "scalar strict identity false success",
                phpc_native_scalar_compare(
                    phpc_native_bool(true),
                    NativeComparisonOp::StrictEq as u8,
                    phpc_native_int(1),
                ),
                0,
            ),
            (
                "value numeric-string ordering success",
                unsafe {
                    phpc_native_value_compare_and_free(
                        NativeValueHandle::from_value(Value::String("10".to_string())),
                        NativeComparisonOp::LooseGt as u8,
                        phpc_native_value_from_scalar(phpc_native_int(2)),
                    )
                },
                0,
            ),
            (
                "array loose blocker",
                unsafe {
                    phpc_native_value_compare_and_free(
                        NativeValueHandle::from_value(Value::Array(PhpArray::new())),
                        NativeComparisonOp::LooseEq as u8,
                        phpc_native_value_from_scalar(phpc_native_int(1)),
                    )
                },
                1,
            ),
            (
                "reference semantic blocker",
                phpc_native_reference_compare(
                    NativeReferenceHandle::null(),
                    NativeComparisonOp::StrictEq as u8,
                    NativeReferenceHandle::null(),
                ),
                1,
            ),
            (
                "invalid opcode blocker",
                phpc_native_scalar_compare(phpc_native_int(1), 99, phpc_native_int(1)),
                1,
            ),
        ] {
            assert_eq!(
                phpc_native_comparison_result_exit_code(result),
                expected_exit_code,
                "{label}"
            );
            let branch =
                unsafe { phpc_native_comparison_result_branch_or_report_stderr_and_free(result) };
            assert_eq!(
                phpc_native_comparison_branch_result_exit_code(branch),
                expected_exit_code,
                "{label}"
            );
        }
    }

