    #[test]
    fn native_array_and_opaque_handle_comparisons_share_result_contract() {
        let left = phpc_native_array_empty();
        let same = phpc_native_array_empty();
        let different = phpc_native_array_empty();
        assert!(unsafe { phpc_native_array_append_scalar(different, phpc_native_int(1)) });

        assert_native_comparison_ok(
            "array strict identity",
            unsafe { phpc_native_array_compare(left, NativeComparisonOp::StrictEq as u8, same) },
            true,
        );
        assert_native_comparison_ok(
            "array strict non-identity",
            unsafe {
                phpc_native_array_compare(left, NativeComparisonOp::StrictNe as u8, different)
            },
            true,
        );
        assert_native_comparison_blocked(
            "array loose blocker",
            unsafe { phpc_native_array_compare(left, NativeComparisonOp::LooseEq as u8, same) },
            "recursive array comparisons are not implemented",
        );

        assert_native_comparison_blocked(
            "object handle blocker",
            phpc_native_object_compare(
                non_null_object_handle_for_test(),
                NativeComparisonOp::LooseEq as u8,
                other_non_null_object_handle_for_test(),
            ),
            "native object handle loose comparisons require shared object property comparison semantics",
        );
        assert_native_comparison_blocked(
            "resource handle blocker",
            phpc_native_resource_compare(
                non_null_resource_handle_for_test(),
                NativeComparisonOp::LooseEq as u8,
                other_non_null_resource_handle_for_test(),
            ),
            "native resource handle loose comparisons require shared resource comparison semantics",
        );
        assert_native_comparison_blocked(
            "reference handle blocker",
            phpc_native_reference_compare(
                NativeReferenceHandle::null(),
                NativeComparisonOp::StrictEq as u8,
                NativeReferenceHandle::null(),
            ),
            "reference comparisons require shared reference dereference semantics",
        );

        unsafe { phpc_native_array_free(left) };
        unsafe { phpc_native_array_free(same) };
        unsafe { phpc_native_array_free(different) };
    }

    #[test]
    fn native_recursive_array_comparison_blocker_feeds_consumers_across_families() {
        fn value_operand(value: Value) -> NativeComparisonOperand {
            NativeComparisonOperand::from_parts(
                NativeValueHandle::from_value(value),
                NativeDiagnosticHandle::null(),
            )
        }

        let expected_message = "recursive array comparisons are not implemented";

        for (label, left, op, right, expected_side) in [
            (
                "left array loose equality",
                Value::Array(PhpArray::new()),
                PhpComparisonOp::LooseEq,
                Value::Int(1),
                ComparisonOperandSide::Left,
            ),
            (
                "right array loose ordering",
                Value::String("needle".to_string()),
                PhpComparisonOp::LooseGt,
                Value::Array(PhpArray::new()),
                ComparisonOperandSide::Right,
            ),
        ] {
            let operation = op.operation_family();
            assert_eq!(
                comparison_blocker_for_family(&left, &right, operation),
                Some(ComparisonBlocker::RecursiveArrayComparison {
                    side: expected_side,
                    operation,
                }),
                "{label}"
            );
            assert!(
                left.php_compare_checked(&right, op)
                    .unwrap_err()
                    .message()
                    .contains(expected_message),
                "{label}"
            );
        }

        assert_native_comparison_blocked(
            "native value left array blocker",
            compare_native_values_for_test(
                Value::Array(PhpArray::new()),
                NativeComparisonOp::LooseEq,
                Value::Int(1),
            ),
            expected_message,
        );

        let array_left = phpc_native_array_empty();
        let array_right = phpc_native_array_empty();
        assert_native_comparison_blocked(
            "native array handle loose blocker",
            unsafe {
                phpc_native_array_compare(
                    array_left,
                    NativeComparisonOp::LooseEq as u8,
                    array_right,
                )
            },
            expected_message,
        );
        unsafe { phpc_native_array_free(array_left) };
        unsafe { phpc_native_array_free(array_right) };

        let branch = unsafe {
            phpc_native_array_compare_branch_and_free(
                phpc_native_array_empty(),
                NativeComparisonOp::LooseGt as u8,
                phpc_native_array_empty(),
            )
        };
        assert_eq!(
            phpc_native_comparison_branch_result_status(branch),
            NativeComparisonStatus::Blocked as u8
        );
        assert!(!phpc_native_comparison_branch_result_is_true(branch));
        assert!(
            phpc_native_comparison_branch_result_diagnostic_len(branch) >= expected_message.len()
        );

        let operation =
            phpc_native_comparison_operation_from_opcode(NativeComparisonOp::LooseEq.abi_opcode());
        let relation = unsafe {
            phpc_native_comparison_operand_compare_operation_relation_and_free(
                value_operand(Value::Array(PhpArray::new())),
                operation,
                phpc_native_comparison_operand_from_scalar(phpc_native_int(1)),
            )
        };
        assert_eq!(
            phpc_native_comparison_relation_result_status(relation),
            NativeComparisonStatus::Blocked as u8
        );
        assert!(phpc_native_comparison_relation_result_is_blocked(relation));
        let diagnostic = phpc_native_comparison_relation_result_diagnostic(relation);
        assert!(native_diagnostic_message_for_test(diagnostic).contains(expected_message));
        unsafe { phpc_native_comparison_relation_result_free(relation) };

        let decision = unsafe {
            phpc_native_comparison_relation_result_decision_or_report_stderr_and_free(
                phpc_native_comparison_operand_compare_operation_relation_and_free(
                    value_operand(Value::String("right".to_string())),
                    operation,
                    value_operand(Value::Array(PhpArray::new())),
                ),
                operation,
            )
        };
        assert_eq!(
            phpc_native_comparison_branch_decision_status(decision),
            NativeComparisonStatus::Blocked as u8
        );
        assert_eq!(
            phpc_native_comparison_branch_decision_exit_code(decision),
            1
        );
        assert!(!phpc_native_comparison_branch_decision_is_true(decision));
    }

    #[test]
    fn native_object_resource_handles_use_relation_result_for_strict_identity() {
        fn assert_relation_ok(
            label: &str,
            result: NativeComparisonRelationResult,
            expected_relation: NativeComparisonRelation,
        ) {
            assert_eq!(
                phpc_native_comparison_relation_result_status(result),
                NativeComparisonStatus::Ok as u8,
                "{label} status",
            );
            assert_eq!(
                phpc_native_comparison_relation_result_relation(result),
                expected_relation as u8,
                "{label} relation",
            );
            assert!(
                phpc_native_comparison_relation_result_diagnostic(result).is_null(),
                "{label} diagnostic",
            );
        }

        let strict_eq =
            phpc_native_comparison_operation_from_opcode(NativeComparisonOp::StrictEq as u8);
        let strict_ne =
            phpc_native_comparison_operation_from_opcode(NativeComparisonOp::StrictNe as u8);

        for (label, left, right, expected_relation, expected_eq, expected_ne) in [
            (
                "object same handle",
                non_null_object_handle_for_test(),
                non_null_object_handle_for_test(),
                NativeComparisonRelation::Equal,
                true,
                false,
            ),
            (
                "object different handles",
                non_null_object_handle_for_test(),
                other_non_null_object_handle_for_test(),
                NativeComparisonRelation::Different,
                false,
                true,
            ),
        ] {
            let relation = phpc_native_object_compare_operation_relation(left, strict_eq, right);
            assert_relation_ok(label, relation, expected_relation);

            assert_native_comparison_ok(
                label,
                phpc_native_object_compare_operation(left, strict_eq, right),
                expected_eq,
            );

            let decision = unsafe {
                phpc_native_comparison_relation_result_decision_or_report_stderr_and_free(
                    phpc_native_object_compare_operation_relation(left, strict_ne, right),
                    strict_ne,
                )
            };
            assert_eq!(
                phpc_native_comparison_branch_decision_exit_code(decision),
                0,
                "{label} decision exit",
            );
            assert_eq!(
                phpc_native_comparison_branch_decision_is_true(decision),
                expected_ne,
                "{label} decision value",
            );
        }

        for (label, left, right, expected_relation, expected_eq, expected_ne) in [
            (
                "resource same handle",
                non_null_resource_handle_for_test(),
                non_null_resource_handle_for_test(),
                NativeComparisonRelation::Equal,
                true,
                false,
            ),
            (
                "resource different handles",
                non_null_resource_handle_for_test(),
                other_non_null_resource_handle_for_test(),
                NativeComparisonRelation::Different,
                false,
                true,
            ),
        ] {
            let relation = phpc_native_resource_compare_relation(
                left,
                NativeComparisonOp::StrictEq as u8,
                right,
            );
            assert_relation_ok(label, relation, expected_relation);

            assert_native_comparison_ok(
                label,
                phpc_native_resource_compare(left, NativeComparisonOp::StrictEq as u8, right),
                expected_eq,
            );

            let decision = unsafe {
                phpc_native_comparison_relation_result_decision_or_report_stderr_and_free(
                    phpc_native_resource_compare_operation_relation(left, strict_ne, right),
                    strict_ne,
                )
            };
            assert_eq!(
                phpc_native_comparison_branch_decision_exit_code(decision),
                0,
                "{label} decision exit",
            );
            assert_eq!(
                phpc_native_comparison_branch_decision_is_true(decision),
                expected_ne,
                "{label} decision value",
            );
        }

        assert_native_comparison_blocked(
            "object loose comparison blocker",
            phpc_native_object_compare(
                non_null_object_handle_for_test(),
                NativeComparisonOp::LooseEq as u8,
                other_non_null_object_handle_for_test(),
            ),
            "native object handle loose comparisons require shared object property comparison semantics",
        );
        assert_native_comparison_blocked(
            "resource loose comparison blocker",
            phpc_native_resource_compare(
                non_null_resource_handle_for_test(),
                NativeComparisonOp::LooseGt as u8,
                other_non_null_resource_handle_for_test(),
            ),
            "native resource handle loose comparisons require shared resource comparison semantics",
        );
        assert_native_comparison_blocked(
            "object null strict blocker",
            phpc_native_object_compare(
                NativeObjectHandle::null(),
                NativeComparisonOp::StrictEq as u8,
                non_null_object_handle_for_test(),
            ),
            "left object handle is null",
        );
        assert_native_comparison_blocked(
            "resource null strict blocker",
            phpc_native_resource_compare(
                non_null_resource_handle_for_test(),
                NativeComparisonOp::StrictNe as u8,
                NativeResourceHandle::null(),
            ),
            "right resource handle is null",
        );
    }

    #[test]
    fn native_array_compare_branch_and_free_reuse_array_result_contract() {
        let left = phpc_native_array_empty();
        let same = phpc_native_array_empty();
        let branch = unsafe {
            phpc_native_array_compare_branch(left, NativeComparisonOp::StrictEq as u8, same)
        };
        assert_eq!(branch.status(), NativeComparisonStatus::Ok as u8);
        assert!(branch.value());
        assert_eq!(branch.diagnostic_len(), 0);
        unsafe { phpc_native_array_free(left) };
        unsafe { phpc_native_array_free(same) };

        let left = phpc_native_array_empty();
        let different = phpc_native_array_empty();
        assert!(unsafe { phpc_native_array_append_scalar(different, phpc_native_int(1)) });
        assert_native_comparison_ok(
            "owned array strict non-identity",
            unsafe {
                phpc_native_array_compare_and_free(
                    left,
                    NativeComparisonOp::StrictNe as u8,
                    different,
                )
            },
            true,
        );

        let alias = phpc_native_array_empty();
        let aliased_branch = unsafe {
            phpc_native_array_compare_branch_and_free(
                alias,
                NativeComparisonOp::StrictEq as u8,
                alias,
            )
        };
        assert_eq!(aliased_branch.status(), NativeComparisonStatus::Ok as u8);
        assert!(aliased_branch.value());
        assert_eq!(aliased_branch.diagnostic_len(), 0);

        let blocked_branch = unsafe {
            phpc_native_array_compare_branch_and_free(
                phpc_native_array_empty(),
                NativeComparisonOp::LooseEq as u8,
                phpc_native_array_empty(),
            )
        };
        assert_eq!(
            blocked_branch.status(),
            NativeComparisonStatus::Blocked as u8
        );
        assert!(!blocked_branch.value());
        assert!(blocked_branch.diagnostic_len() > 0);

        assert_native_comparison_blocked(
            "owned array invalid opcode",
            unsafe {
                phpc_native_array_compare_and_free(
                    phpc_native_array_empty(),
                    99,
                    NativeArrayHandle::null(),
                )
            },
            "unsupported comparison opcode",
        );

        let null_branch = unsafe {
            phpc_native_array_compare_branch_and_free(
                NativeArrayHandle::null(),
                NativeComparisonOp::StrictEq as u8,
                phpc_native_array_empty(),
            )
        };
        assert_eq!(null_branch.status(), NativeComparisonStatus::Blocked as u8);
        assert!(!null_branch.value());
        assert!(null_branch.diagnostic_len() > 0);
    }

    #[test]
    fn echo_conversions_match_php_scalars_for_supported_values() {
        assert_eq!(Value::Null.echo_string(), "");
        assert_eq!(Value::Bool(false).echo_string(), "");
        assert_eq!(Value::Bool(true).echo_string(), "1");
        assert_eq!(Value::Int(42).echo_string(), "42");
        assert_eq!(Value::Float(1.5).echo_string(), "1.5");
        assert_eq!(Value::String("x".to_string()).echo_string(), "x");
    }

    #[test]
    fn value_string_semantics_feed_echo_scalar_array_and_native_consumers() {
        let mut array = PhpArray::new();
        array.insert("item", Value::Int(1));

        let cases = vec![
            ("null", Value::Null, b"".as_slice(), true),
            ("false", Value::Bool(false), b"", true),
            ("true", Value::Bool(true), b"1", true),
            ("int", Value::Int(-42), b"-42", true),
            ("float", Value::Float(1.5), b"1.5", true),
            (
                "string",
                Value::String("php\0value".to_string()),
                b"php\0value",
                true,
            ),
            ("array", Value::Array(array), b"Array", false),
        ];

        for (label, value, expected, scalar_string_allowed) in cases {
            let expected_text = String::from_utf8_lossy(expected);
            let semantics = analyze_php_value_string_semantics(&value);
            assert_eq!(
                semantics.as_str(),
                expected_text,
                "shared string semantics for {label}"
            );
            assert_eq!(
                semantics.clone().into_string().as_bytes(),
                expected,
                "owned string semantics result for {label}"
            );
            assert_eq!(
                value.echo_string().as_bytes(),
                expected,
                "legacy echo string consumer for {label}"
            );
            assert_eq!(
                value.try_echo_string().unwrap().as_bytes(),
                expected,
                "checked echo conversion consumer for {label}"
            );

            let handle = NativeValueHandle::from_value(value.clone());
            let result = unsafe { phpc_native_value_to_string_bytes(handle) };
            assert_eq!(
                native_string_conversion_result_for_test(result).unwrap(),
                expected,
                "native conversion result consumer for {label}"
            );
            unsafe { phpc_native_value_free(handle) };

            if scalar_string_allowed {
                assert_eq!(
                    value.php_scalar_string_bytes().as_deref(),
                    Some(expected),
                    "scalar string bytes consumer for {label}"
                );
                assert_eq!(
                    array_scalar_string_comparison_value("array_diff()", &value)
                        .unwrap()
                        .as_slice(),
                    expected,
                    "array string comparison consumer for {label}"
                );
            } else {
                assert_eq!(
                    value.php_scalar_string_bytes(),
                    None,
                    "scalar string blocker for {label}"
                );
                assert!(
                    array_scalar_string_comparison_value("array_diff()", &value).is_err(),
                    "array string comparison blocker for {label}"
                );
            }
        }

        let classes = PhpClassTable::with_core_classes();
        let class = classes.lookup_class("stdClass").unwrap();
        let object = Value::Object(PhpObject::from_class(class));
        assert_eq!(
            analyze_php_value_string_semantics(&object).as_str(),
            "Object"
        );
        assert!(object.try_echo_string().is_err());

        let closure = Value::Closure(PhpClosure::new(1, false, Vec::new()));
        assert_eq!(
            analyze_php_value_string_semantics(&closure).as_str(),
            "Object"
        );
        assert!(closure.try_echo_string().is_err());

        let resource = Value::Resource(7);
        assert_eq!(
            analyze_php_value_string_semantics(&resource).as_str(),
            "Resource id #7"
        );
        assert!(resource.try_echo_string().is_err());
    }

