    #[test]
    fn native_request_state_operation_kind_maps_shared_abi_contract() {
        for (
            tag,
            expected,
            expected_address_family,
            uses_keyed_scalar_snapshot,
            owns_value,
            owns_array,
        ) in [
            (
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                NativeRequestStateOperationKind::Value,
                NativeRequestStateOperationAddressFamily::KeyedScalarSnapshot,
                true,
                true,
                false,
            ),
            (
                PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                NativeRequestStateOperationKind::Array,
                NativeRequestStateOperationAddressFamily::BagSnapshot,
                false,
                false,
                true,
            ),
            (
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                NativeRequestStateOperationKind::Presence,
                NativeRequestStateOperationAddressFamily::KeyedScalarSnapshot,
                true,
                false,
                false,
            ),
            (
                PHPC_NATIVE_REQUEST_STATE_OP_BAG_PRESENCE,
                NativeRequestStateOperationKind::BagPresence,
                NativeRequestStateOperationAddressFamily::BagSnapshot,
                false,
                false,
                false,
            ),
        ] {
            let operation_kind = NativeRequestStateOperationKind::from_abi_tag(tag)
                .expect("request-state operation tag is supported");

            assert_eq!(operation_kind, expected);
            assert_eq!(operation_kind.address_family(), expected_address_family);
            assert_eq!(
                operation_kind.uses_keyed_scalar_snapshot(),
                uses_keyed_scalar_snapshot
            );
            assert_eq!(
                operation_kind.uses_bag_snapshot(),
                !uses_keyed_scalar_snapshot
            );
            assert_eq!(operation_kind.owns_value_handle(), owns_value);
            assert_eq!(operation_kind.owns_array_handle(), owns_array);
            assert_eq!(
                operation_kind.owns_runtime_handle(),
                owns_value || owns_array
            );
        }

        assert_eq!(NativeRequestStateOperationKind::from_abi_tag(0), None);
        assert_eq!(NativeRequestStateOperationKind::from_abi_tag(99), None);
    }

    #[test]
    fn native_request_state_key_abi_coerces_scalar_and_value_key_families() {
        for (value, expected) in [
            (NativeScalarValue::null(), b"".as_slice()),
            (NativeScalarValue::bool(false), b"0".as_slice()),
            (NativeScalarValue::bool(true), b"1".as_slice()),
            (NativeScalarValue::int(-42), b"-42".as_slice()),
            (NativeScalarValue::float(42.0), b"42".as_slice()),
            (NativeScalarValue::float(-0.0), b"0".as_slice()),
        ] {
            let key = phpc_native_request_state_key_from_scalar(value);

            assert_eq!(key.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(native_byte_buffer_to_vec_for_test(key.buffer), expected);
        }

        for value in [
            NativeScalarValue::float(1.5),
            NativeScalarValue::float(f64::INFINITY),
            NativeScalarValue::float(f64::NAN),
        ] {
            let key = phpc_native_request_state_key_from_scalar(value);

            assert_eq!(
                key.status,
                PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEY_COERCION
            );
            assert_eq!(native_byte_buffer_to_vec_for_test(key.buffer), b"");
        }

        for (value, expected) in [
            (Value::Null, b"".as_slice()),
            (Value::Bool(false), b"0".as_slice()),
            (Value::Bool(true), b"1".as_slice()),
            (Value::Int(-42), b"-42".as_slice()),
            (Value::Float(42.0), b"42".as_slice()),
            (
                Value::String("text-key".to_string()),
                b"text-key".as_slice(),
            ),
        ] {
            let handle = NativeValueHandle::from_value(value);
            let key = unsafe { phpc_native_request_state_key_from_value(handle) };

            assert_eq!(key.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(native_byte_buffer_to_vec_for_test(key.buffer), expected);
            unsafe { phpc_native_value_free(handle) };
        }

        for value in [
            Value::Float(1.5),
            Value::Float(f64::INFINITY),
            Value::Array(PhpArray::new()),
        ] {
            let handle = NativeValueHandle::from_value(value);
            let key = unsafe { phpc_native_request_state_key_from_value(handle) };

            assert_eq!(
                key.status,
                PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEY_COERCION
            );
            assert_eq!(native_byte_buffer_to_vec_for_test(key.buffer), b"");
            unsafe { phpc_native_value_free(handle) };
        }

        let null_key =
            unsafe { phpc_native_request_state_key_from_value(NativeValueHandle::null()) };
        assert_eq!(
            null_key.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_ABI
        );
        assert_eq!(native_byte_buffer_to_vec_for_test(null_key.buffer), b"");
    }

    #[test]
    fn native_request_state_operations_preserve_php_value_snapshots_and_isset_semantics() {
        let request_state = phpc_native_request_state_empty();
        let bag = b"_GET";

        let null_key = b"null-value";
        let null_value = NativeValueHandle::from_value(Value::Null);
        assert!(unsafe {
            phpc_native_request_state_insert_superglobal_value(
                request_state,
                bag.as_ptr(),
                bag.len(),
                null_key.as_ptr(),
                null_key.len(),
                null_value,
            )
        });

        let text_key = b"text";
        let text_value = NativeValueHandle::from_value(Value::String("A\0B".to_string()));
        assert!(unsafe {
            phpc_native_request_state_insert_superglobal_value(
                request_state,
                bag.as_ptr(),
                bag.len(),
                text_key.as_ptr(),
                text_key.len(),
                text_value,
            )
        });

        let mut nested = PhpArray::new();
        nested.insert(
            ArrayKey::string("child"),
            Value::String("nested".to_string()),
        );
        let array_key = b"array-value";
        let array_value = NativeValueHandle::from_value(Value::Array(nested.clone()));
        assert!(unsafe {
            phpc_native_request_state_insert_superglobal_value(
                request_state,
                bag.as_ptr(),
                bag.len(),
                array_key.as_ptr(),
                array_key.len(),
                array_value,
            )
        });

        let null_presence = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                bag,
                Some(null_key),
            )
        };
        assert_eq!(
            null_presence.result_kind,
            PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE
        );
        assert_eq!(null_presence.exists, 1);
        assert_eq!(null_presence.is_set, 0);
        assert_eq!(null_presence.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);

        let null_result = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                bag,
                Some(null_key),
            )
        };
        assert_eq!(null_result.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
        assert_eq!(null_result.exists, 1);
        assert_eq!(null_result.is_set, 0);
        assert_eq!(unsafe { null_result.value.as_ref() }, Some(&Value::Null));
        unsafe { phpc_native_request_state_operation_result_free(null_result) };

        let text_result = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                bag,
                Some(text_key),
            )
        };
        assert_eq!(text_result.exists, 1);
        assert_eq!(text_result.is_set, 1);
        assert_eq!(
            unsafe { text_result.value.as_ref() },
            Some(&Value::String("A\0B".to_string()))
        );
        unsafe { phpc_native_request_state_operation_result_free(text_result) };

        let array_result = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                bag,
                Some(array_key),
            )
        };
        assert_eq!(array_result.exists, 1);
        assert_eq!(array_result.is_set, 1);
        assert_eq!(
            unsafe { array_result.value.as_ref() },
            Some(&Value::Array(nested))
        );
        unsafe { phpc_native_request_state_operation_result_free(array_result) };

        let missing = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                bag,
                Some(b"missing"),
            )
        };
        assert_eq!(missing.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
        assert_eq!(missing.exists, 0);
        assert_eq!(missing.is_set, 0);
        assert_eq!(missing.status, PHPC_NATIVE_REQUEST_STATE_STATUS_MISSING_KEY);
        assert_eq!(unsafe { missing.value.as_ref() }, Some(&Value::Null));
        unsafe { phpc_native_request_state_operation_result_free(missing) };

        let snapshot = unsafe {
            phpc_native_request_state_superglobal_array(request_state, bag.as_ptr(), bag.len())
        };
        let snapshot_array = unsafe { snapshot.as_ref() }.expect("snapshot array handle is valid");
        assert_eq!(snapshot_array.value.len(), 3);
        assert_eq!(
            snapshot_array.value.get(ArrayKey::string("null-value")),
            Some(&Value::Null)
        );
        assert_eq!(
            snapshot_array.value.get(ArrayKey::string("text")),
            Some(&Value::String("A\0B".to_string()))
        );

        assert!(!unsafe {
            phpc_native_request_state_insert_superglobal_value(
                request_state,
                b"_UNKNOWN".as_ptr(),
                b"_UNKNOWN".len(),
                null_key.as_ptr(),
                null_key.len(),
                null_value,
            )
        });
        assert!(!unsafe {
            phpc_native_request_state_insert_superglobal_value(
                request_state,
                bag.as_ptr(),
                bag.len(),
                null_key.as_ptr(),
                null_key.len(),
                NativeValueHandle::null(),
            )
        });

        unsafe { phpc_native_array_free(snapshot) };
        unsafe { phpc_native_value_free(array_value) };
        unsafe { phpc_native_value_free(text_value) };
        unsafe { phpc_native_value_free(null_value) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_root_replacements_store_direct_values_and_reenter_slot_tables() {
        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn snapshot_value(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
        ) -> Value {
            let snapshot = unsafe {
                phpc_native_request_state_superglobal_snapshot_value(request_state, root)
            };
            let value = unsafe { snapshot.as_ref() }
                .expect("request root snapshots should return a value")
                .clone();
            unsafe { phpc_native_value_free(snapshot) };
            value
        }

        unsafe fn replace_root(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
            value: Value,
        ) {
            let value = NativeValueHandle::from_value(value);
            let mut diagnostic = NativeDiagnosticHandle::null();
            let replaced = unsafe {
                phpc_native_request_state_superglobal_replace_value_with_diagnostic(
                    request_state,
                    root,
                    value,
                    &mut diagnostic,
                )
            };
            unsafe { phpc_native_value_free(value) };
            if !diagnostic.is_null() {
                let message = native_diagnostic_message_for_test(diagnostic);
                unsafe { phpc_native_diagnostic_free(diagnostic) };
                panic!("{message}");
            }
            assert!(replaced);
        }

        fn assert_array_slot(value: &Value, key: &str, expected: Value) {
            let Value::Array(array) = value else {
                panic!("request root should be array-backed");
            };
            assert_eq!(array.get_cloned(ArrayKey::string(key)), Some(expected));
        }

        let request_state = phpc_native_request_state_empty();
        let get_root = unsafe { string_handle(b"_GET") };
        let post_root = unsafe { string_handle(b"_POST") };
        let request_root = unsafe { string_handle(b"_REQUEST") };

        let stale_value = NativeValueHandle::from_value(Value::String("stale".to_string()));
        assert!(unsafe {
            phpc_native_request_state_insert_superglobal_value(
                request_state,
                b"_GET".as_ptr(),
                b"_GET".len(),
                b"stale".as_ptr(),
                b"stale".len(),
                stale_value,
            )
        });
        unsafe { phpc_native_value_free(stale_value) };
        assert_array_slot(
            &unsafe { snapshot_value(request_state, get_root) },
            "stale",
            Value::String("stale".to_string()),
        );

        unsafe {
            replace_root(
                request_state,
                get_root,
                Value::String("direct-root".to_string()),
            )
        };
        assert_eq!(
            unsafe { snapshot_value(request_state, get_root) },
            Value::String("direct-root".to_string())
        );

        let stale_read = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_GET",
                Some(b"stale"),
            )
        };
        assert_eq!(
            stale_read.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_VALUE
        );
        assert_eq!(unsafe { stale_read.value.as_ref() }, Some(&Value::Null));
        unsafe { phpc_native_request_state_operation_result_free(stale_read) };

        let blocked_value = NativeValueHandle::from_value(Value::Int(8));
        let blocked_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                b"blocked",
                blocked_value,
            )
        };
        unsafe { phpc_native_value_free(blocked_value) };
        assert_eq!(
            blocked_write.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_VALUE
        );
        assert_eq!(blocked_write.result_kind, 0);
        assert_eq!(blocked_write.is_set, 0);
        assert_eq!(blocked_write.exists, 0);
        assert!(blocked_write.value.is_null());
        assert!(blocked_write.array.is_null());
        assert_eq!(
            unsafe { snapshot_value(request_state, get_root) },
            Value::String("direct-root".to_string())
        );

        unsafe { replace_root(request_state, get_root, Value::Null) };
        let fresh_value = NativeValueHandle::from_value(Value::Int(7));
        let fresh_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                b"fresh",
                fresh_value,
            )
        };
        unsafe { phpc_native_value_free(fresh_value) };
        assert_request_state_presence_result_for_test(
            fresh_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let get_snapshot = unsafe { snapshot_value(request_state, get_root) };
        assert_array_slot(&get_snapshot, "fresh", Value::Int(7));
        let Value::Array(get_array) = get_snapshot else {
            panic!("indexed writes should re-enter array-backed request storage");
        };
        assert_eq!(get_array.get_cloned(ArrayKey::string("stale")), None);

        unsafe { replace_root(request_state, post_root, Value::Null) };
        let nested_value = NativeValueHandle::from_value(Value::Bool(true));
        let nested_write = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_POST",
                &[b"root", b"leaf"],
                nested_value,
            )
        };
        unsafe { phpc_native_value_free(nested_value) };
        assert_request_state_presence_result_for_test(
            nested_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let post_snapshot = unsafe { snapshot_value(request_state, post_root) };
        let Value::Array(post_array) = post_snapshot else {
            panic!("path writes should re-enter array-backed request storage");
        };
        let Some(Value::Array(root_array)) = post_array.get_cloned(ArrayKey::string("root")) else {
            panic!("path writes should materialize nested request arrays");
        };
        assert_eq!(
            root_array.get_cloned(ArrayKey::string("leaf")),
            Some(Value::Bool(true))
        );

        let mut request_array = PhpArray::new();
        request_array.insert(
            ArrayKey::string("id"),
            Value::String("array-root".to_string()),
        );
        unsafe { replace_root(request_state, request_root, Value::Array(request_array)) };
        assert_array_slot(
            &unsafe { snapshot_value(request_state, request_root) },
            "id",
            Value::String("array-root".to_string()),
        );

        let request_read = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_REQUEST",
                Some(b"id"),
            )
        };
        assert_eq!(request_read.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
        assert_eq!(
            unsafe { request_read.value.as_ref() },
            Some(&Value::String("array-root".to_string()))
        );
        unsafe { phpc_native_request_state_operation_result_free(request_read) };

        unsafe { phpc_native_string_free(request_root) };
        unsafe { phpc_native_string_free(post_root) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_root_reference_replacements_share_direct_cells_and_block_keyed_mutation(
    ) {
        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn snapshot_value(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
        ) -> Value {
            let snapshot = unsafe {
                phpc_native_request_state_superglobal_snapshot_value(request_state, root)
            };
            let value = unsafe { snapshot.as_ref() }
                .expect("request root snapshots should return a value")
                .clone();
            unsafe { phpc_native_value_free(snapshot) };
            value
        }

        unsafe fn replace_reference(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
            reference: NativeReferenceHandle,
        ) {
            let mut diagnostic = NativeDiagnosticHandle::null();
            let replaced = unsafe {
                phpc_native_request_state_superglobal_replace_reference_with_diagnostic(
                    request_state,
                    root,
                    reference,
                    &mut diagnostic,
                )
            };
            if !diagnostic.is_null() {
                let message = native_diagnostic_message_for_test(diagnostic);
                unsafe { phpc_native_diagnostic_free(diagnostic) };
                panic!("{message}");
            }
            assert!(replaced);
        }

        unsafe fn set_reference_value(reference: NativeReferenceHandle, value: Value) {
            let value = NativeValueHandle::from_value(value);
            assert!(unsafe { phpc_native_reference_set_value(reference, value) });
            unsafe { phpc_native_value_free(value) };
        }

        let request_state = phpc_native_request_state_empty();
        let get_root = unsafe { string_handle(b"_GET") };
        let post_root = unsafe { string_handle(b"_POST") };
        let request_root = unsafe { string_handle(b"_REQUEST") };
        let invalid_root = unsafe { string_handle(b"_NOPE") };
        let roots = [
            (get_root, b"_GET".as_slice()),
            (post_root, b"_POST".as_slice()),
            (request_root, b"_REQUEST".as_slice()),
        ];
        let reference = native_reference_from_value(Value::String("seed".to_string()));
        assert!(!phpc_native_reference_is_null(reference));

        let stale_value = NativeValueHandle::from_value(Value::String("stale".to_string()));
        for (root, bag) in roots {
            assert!(unsafe {
                phpc_native_request_state_insert_superglobal_value(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    b"stale".as_ptr(),
                    b"stale".len(),
                    stale_value,
                )
            });
            unsafe { replace_reference(request_state, root, reference) };

            let stale_read = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag,
                    Some(b"stale"),
                )
            };
            assert_eq!(
                stale_read.status,
                PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_VALUE
            );
            assert_eq!(unsafe { stale_read.value.as_ref() }, Some(&Value::Null));
            unsafe { phpc_native_request_state_operation_result_free(stale_read) };
            assert_eq!(
                unsafe { snapshot_value(request_state, root) },
                Value::String("seed".to_string())
            );
        }
        unsafe { phpc_native_value_free(stale_value) };

        let mut referenced_array = PhpArray::new();
        referenced_array.insert(
            ArrayKey::string("id"),
            Value::String("array-ref".to_string()),
        );
        unsafe { set_reference_value(reference, Value::Array(referenced_array)) };
        for (_, bag) in roots {
            let keyed_read = unsafe {
                request_state_operation_for_test(
                    request_state,
                    PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                    bag,
                    Some(b"id"),
                )
            };
            assert_eq!(keyed_read.status, PHPC_NATIVE_REQUEST_STATE_STATUS_OK);
            assert_eq!(
                unsafe { keyed_read.value.as_ref() },
                Some(&Value::String("array-ref".to_string()))
            );
            unsafe { phpc_native_request_state_operation_result_free(keyed_read) };
        }

        let blocked_value = NativeValueHandle::from_value(Value::Int(9));
        let blocked_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                b"new",
                blocked_value,
            )
        };
        unsafe { phpc_native_value_free(blocked_value) };
        assert_eq!(
            blocked_write.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_VALUE
        );
        assert_eq!(
            unsafe { snapshot_value(request_state, get_root) },
            Value::Array({
                let mut array = PhpArray::new();
                array.insert(
                    ArrayKey::string("id"),
                    Value::String("array-ref".to_string()),
                );
                array
            })
        );

        unsafe { set_reference_value(reference, Value::String("updated".to_string())) };
        for (root, _) in roots {
            assert_eq!(
                unsafe { snapshot_value(request_state, root) },
                Value::String("updated".to_string())
            );
        }

        unsafe { set_reference_value(reference, Value::Null) };
        for (root, _) in roots {
            assert_eq!(unsafe { snapshot_value(request_state, root) }, Value::Null);
        }

        let mut diagnostic = NativeDiagnosticHandle::null();
        assert!(!unsafe {
            phpc_native_request_state_superglobal_replace_reference_with_diagnostic(
                request_state,
                invalid_root,
                reference,
                &mut diagnostic,
            )
        });
        assert!(!diagnostic.is_null());
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        diagnostic = NativeDiagnosticHandle::null();
        assert!(!unsafe {
            phpc_native_request_state_superglobal_replace_reference_with_diagnostic(
                request_state,
                get_root,
                NativeReferenceHandle::null(),
                &mut diagnostic,
            )
        });
        assert!(!diagnostic.is_null());
        unsafe { phpc_native_diagnostic_free(diagnostic) };

        unsafe { phpc_native_reference_free(reference) };
        unsafe { phpc_native_string_free(invalid_root) };
        unsafe { phpc_native_string_free(request_root) };
        unsafe { phpc_native_string_free(post_root) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_keyed_mutation_updates_multiple_superglobal_bags() {
        let request_state = phpc_native_request_state_empty();
        let get_key = b"cart-id";
        let get_value = NativeValueHandle::from_value(Value::String("A\0B".to_string()));
        let get_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                get_key,
                get_value,
            )
        };
        assert_request_state_presence_result_for_test(
            get_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );

        let get_read = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_GET",
                Some(get_key),
            )
        };
        assert_eq!(get_read.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
        assert_eq!(get_read.exists, 1);
        assert_eq!(get_read.is_set, 1);
        assert_eq!(
            unsafe { get_read.value.as_ref() },
            Some(&Value::String("A\0B".to_string()))
        );
        unsafe { phpc_native_request_state_operation_result_free(get_read) };

        let files_key = b"upload";
        let files_value = NativeValueHandle::from_value(Value::Int(7));
        let files_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_FILES",
                files_key,
                files_value,
            )
        };
        assert_request_state_presence_result_for_test(
            files_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let files_array = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_ARRAY,
                b"_FILES",
                None,
            )
        };
        assert_eq!(files_array.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_ARRAY);
        let files_array_ref =
            unsafe { files_array.array.as_ref() }.expect("files array result is owned");
        assert_eq!(files_array_ref.value.len(), 1);
        assert_eq!(
            files_array_ref.value.get_cloned(ArrayKey::string("upload")),
            Some(Value::Int(7))
        );
        unsafe { phpc_native_request_state_operation_result_free(files_array) };

        let get_unset = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_UNSET,
                b"_GET",
                get_key,
                NativeValueHandle::null(),
            )
        };
        assert_request_state_presence_result_for_test(
            get_unset,
            0,
            0,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let get_presence = unsafe {
            request_state_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                b"_GET",
                Some(get_key),
            )
        };
        assert_request_state_presence_result_for_test(
            get_presence,
            0,
            0,
            PHPC_NATIVE_REQUEST_STATE_STATUS_MISSING_KEY,
        );

        let invalid_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_POST",
                b"missing-value",
                NativeValueHandle::null(),
            )
        };
        assert_eq!(invalid_write.result_kind, 0);
        assert_eq!(
            invalid_write.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_ABI
        );

        let invalid_kind = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                99,
                b"_POST",
                b"slot",
                NativeValueHandle::null(),
            )
        };
        assert_eq!(invalid_kind.result_kind, 0);
        assert_eq!(
            invalid_kind.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_OPERATION
        );

        unsafe { phpc_native_value_free(files_value) };
        unsafe { phpc_native_value_free(get_value) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_path_mutation_shares_nested_key_semantics() {
        let request_state = phpc_native_request_state_empty();
        let nested_keys: [&[u8]; 3] = [b"cart", b"item", b"name"];
        let nested_value = NativeValueHandle::from_value(Value::String("P\0Q".to_string()));
        let nested_write = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_POST",
                &nested_keys,
                nested_value,
            )
        };
        assert_request_state_presence_result_for_test(
            nested_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let nested_read = unsafe {
            request_state_path_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_POST",
                &nested_keys,
            )
        };
        assert_eq!(nested_read.result_kind, PHPC_NATIVE_REQUEST_STATE_OP_VALUE);
        assert_eq!(nested_read.exists, 1);
        assert_eq!(nested_read.is_set, 1);
        assert_eq!(
            unsafe { nested_read.value.as_ref() },
            Some(&Value::String("P\0Q".to_string()))
        );
        unsafe { phpc_native_request_state_operation_result_free(nested_read) };

        let null_root = NativeValueHandle::from_value(Value::Null);
        let null_root_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_REQUEST",
                b"root",
                null_root,
            )
        };
        assert_request_state_presence_result_for_test(
            null_root_write,
            0,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let null_path_value = NativeValueHandle::from_value(Value::Int(12));
        let null_path_keys: [&[u8]; 2] = [b"root", b"leaf"];
        let null_path_write = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_REQUEST",
                &null_path_keys,
                null_path_value,
            )
        };
        assert_request_state_presence_result_for_test(
            null_path_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let null_path_read = unsafe {
            request_state_path_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_REQUEST",
                &null_path_keys,
            )
        };
        assert_eq!(
            unsafe { null_path_read.value.as_ref() },
            Some(&Value::Int(12))
        );
        unsafe { phpc_native_request_state_operation_result_free(null_path_read) };

        let false_root = NativeValueHandle::from_value(Value::Bool(false));
        let false_root_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_COOKIE",
                b"root",
                false_root,
            )
        };
        assert_request_state_presence_result_for_test(
            false_root_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let false_path_value = NativeValueHandle::from_value(Value::Bool(true));
        let false_path_keys: [&[u8]; 2] = [b"root", b"enabled"];
        let false_path_write = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_COOKIE",
                &false_path_keys,
                false_path_value,
            )
        };
        assert_request_state_presence_result_for_test(
            false_path_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let false_path_read = unsafe {
            request_state_path_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                b"_COOKIE",
                &false_path_keys,
            )
        };
        assert_eq!(
            unsafe { false_path_read.value.as_ref() },
            Some(&Value::Bool(true))
        );
        unsafe { phpc_native_request_state_operation_result_free(false_path_read) };

        let scalar_root = NativeValueHandle::from_value(Value::String("x".to_string()));
        let scalar_root_write = unsafe {
            request_state_keyed_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                b"scalar",
                scalar_root,
            )
        };
        assert_request_state_presence_result_for_test(
            scalar_root_write,
            1,
            1,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let scalar_path_value = NativeValueHandle::from_value(Value::Int(99));
        let scalar_path_keys: [&[u8]; 2] = [b"scalar", b"child"];
        let scalar_path_write = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_WRITE,
                b"_GET",
                &scalar_path_keys,
                scalar_path_value,
            )
        };
        assert_eq!(scalar_path_write.result_kind, 0);
        assert_eq!(
            scalar_path_write.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_UNSUPPORTED_KEYED_VALUE
        );

        let nested_unset = unsafe {
            request_state_path_mutation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_UNSET,
                b"_POST",
                &nested_keys,
                NativeValueHandle::null(),
            )
        };
        assert_request_state_presence_result_for_test(
            nested_unset,
            0,
            0,
            PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
        );
        let nested_presence = unsafe {
            request_state_path_operation_for_test(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                b"_POST",
                &nested_keys,
            )
        };
        assert_request_state_presence_result_for_test(
            nested_presence,
            0,
            0,
            PHPC_NATIVE_REQUEST_STATE_STATUS_MISSING_KEY,
        );

        let invalid_path = unsafe {
            phpc_native_request_state_superglobal_path_mutation_operation(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_MUTATION_UNSET,
                b"_POST".as_ptr(),
                b"_POST".len(),
                ptr::null(),
                ptr::null(),
                0,
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
                NativeValueHandle::null(),
            )
        };
        assert_eq!(invalid_path.result_kind, 0);
        assert_eq!(
            invalid_path.status,
            PHPC_NATIVE_REQUEST_STATE_STATUS_INVALID_ABI
        );

        unsafe { phpc_native_value_free(scalar_path_value) };
        unsafe { phpc_native_value_free(scalar_root) };
        unsafe { phpc_native_value_free(false_path_value) };
        unsafe { phpc_native_value_free(false_root) };
        unsafe { phpc_native_value_free(null_path_value) };
        unsafe { phpc_native_value_free(null_root) };
        unsafe { phpc_native_value_free(nested_value) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_rebuilds_request_and_snapshots_backing_tables() {
        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn insert_string(
            request_state: NativeRequestStateHandle,
            bag: &[u8],
            key: &[u8],
            value: &str,
        ) {
            let value = NativeValueHandle::from_value(Value::String(value.to_string()));
            assert!(unsafe {
                phpc_native_request_state_insert_superglobal_value(
                    request_state,
                    bag.as_ptr(),
                    bag.len(),
                    key.as_ptr(),
                    key.len(),
                    value,
                )
            });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn assert_value_echo_and_free(handle: NativeValueHandle, expected: &[u8]) {
            assert_eq!(native_value_echo_bytes_for_test(handle), expected);
            unsafe { phpc_native_value_free(handle) };
        }

        unsafe fn assert_snapshot_slot(snapshot: NativeValueHandle, key: &str, expected: &str) {
            let Some(Value::Array(array)) = (unsafe { snapshot.as_ref() }) else {
                panic!("request snapshot should materialize an array value");
            };
            assert_eq!(
                array.get(ArrayKey::string(key)),
                Some(&Value::String(expected.to_string()))
            );
        }

        unsafe fn assert_missing_snapshot_slot(snapshot: NativeValueHandle, key: &str) {
            let Some(Value::Array(array)) = (unsafe { snapshot.as_ref() }) else {
                panic!("request snapshot should materialize an array value");
            };
            assert_eq!(array.get(ArrayKey::string(key)), None);
        }

        let request_state = phpc_native_request_state_empty();
        let get_root = unsafe { string_handle(b"_GET") };
        let request_root = unsafe { string_handle(b"_REQUEST") };
        let invalid_root = unsafe { string_handle(b"_NOPE") };
        let order_gp = unsafe { string_handle(b"GP") };
        let order_cg = unsafe { string_handle(b"CG") };
        let order_g = unsafe { string_handle(b"G") };
        let request_order_pg = unsafe { string_handle(b"PG") };
        let empty_request_order = unsafe { string_handle(b"") };
        let variables_order_egpsc = unsafe { string_handle(b"EGPSC") };
        let variables_order_cg = unsafe { string_handle(b"CG") };

        unsafe { insert_string(request_state, b"_GET", b"id", "get") };
        unsafe { insert_string(request_state, b"_POST", b"id", "post") };
        unsafe { insert_string(request_state, b"_COOKIE", b"id", "cookie") };
        unsafe { insert_string(request_state, b"_COOKIE", b"sid", "cookie-session") };
        unsafe { insert_string(request_state, b"_REQUEST", b"stale", "stale-request") };

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_order(request_state, order_gp)
        });
        unsafe {
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                b"post",
            );
        }

        let request_snapshot = unsafe {
            phpc_native_request_state_superglobal_snapshot_value(request_state, request_root)
        };
        let get_snapshot = unsafe {
            phpc_native_request_state_superglobal_snapshot_value(request_state, get_root)
        };
        assert!(!request_snapshot.is_null());
        assert!(!get_snapshot.is_null());
        unsafe {
            assert_snapshot_slot(request_snapshot, "id", "post");
            assert_missing_snapshot_slot(request_snapshot, "sid");
            assert_missing_snapshot_slot(request_snapshot, "stale");
            assert_snapshot_slot(get_snapshot, "id", "get");
        }

        unsafe { insert_string(request_state, b"_POST", b"id", "post-after-snapshot") };
        unsafe {
            assert_snapshot_slot(request_snapshot, "id", "post");
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_POST".as_ptr(),
                    b"_POST".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                b"post-after-snapshot",
            );
        }

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_order(request_state, order_cg)
        });
        unsafe {
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                b"get",
            );
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"sid".as_ptr(),
                    b"sid".len(),
                ),
                b"cookie-session",
            );
        }

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_order(request_state, order_g)
        });
        let request_after_g = unsafe {
            phpc_native_request_state_superglobal_snapshot_value(request_state, request_root)
        };
        unsafe {
            assert_snapshot_slot(request_after_g, "id", "get");
            assert_missing_snapshot_slot(request_after_g, "sid");
            phpc_native_value_free(request_after_g);
        }

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_policy(
                request_state,
                request_order_pg,
                variables_order_cg,
            )
        });
        unsafe {
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                b"get",
            );
        }

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_policy(
                request_state,
                empty_request_order,
                variables_order_egpsc,
            )
        });
        unsafe {
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                b"cookie",
            );
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"sid".as_ptr(),
                    b"sid".len(),
                ),
                b"cookie-session",
            );
        }

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_policy(
                request_state,
                NativeStringHandle::null(),
                variables_order_cg,
            )
        });
        unsafe {
            assert_value_echo_and_free(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_REQUEST".as_ptr(),
                    b"_REQUEST".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                b"get",
            );
        }

        assert!(unsafe {
            phpc_native_request_state_superglobal_snapshot_value(request_state, invalid_root)
        }
        .is_null());
        assert!(!unsafe {
            phpc_native_request_state_rebuild_request_from_order(
                NativeRequestStateHandle::null(),
                order_g,
            )
        });
        assert!(!unsafe {
            phpc_native_request_state_rebuild_request_from_policy(
                request_state,
                NativeStringHandle::null(),
                NativeStringHandle::null(),
            )
        });

        unsafe { phpc_native_value_free(request_snapshot) };
        unsafe { phpc_native_value_free(get_snapshot) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_string_free(request_root) };
        unsafe { phpc_native_string_free(invalid_root) };
        unsafe { phpc_native_string_free(order_gp) };
        unsafe { phpc_native_string_free(order_cg) };
        unsafe { phpc_native_string_free(order_g) };
        unsafe { phpc_native_string_free(request_order_pg) };
        unsafe { phpc_native_string_free(empty_request_order) };
        unsafe { phpc_native_string_free(variables_order_egpsc) };
        unsafe { phpc_native_string_free(variables_order_cg) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_populates_sapi_roots_from_symbol_table_sources() {
        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn write_symbol(table: NativeSymbolTableHandle, name: &[u8], value: Value) {
            let value = NativeValueHandle::from_value(value);
            assert!(unsafe {
                phpc_native_symbol_table_write(table, name.as_ptr(), name.len(), value)
            });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn snapshot(
            request_state: NativeRequestStateHandle,
            root: NativeStringHandle,
        ) -> NativeValueHandle {
            unsafe { phpc_native_request_state_superglobal_snapshot_value(request_state, root) }
        }

        unsafe fn assert_slot(snapshot: NativeValueHandle, key: &str, expected: Value) {
            let Some(Value::Array(array)) = (unsafe { snapshot.as_ref() }) else {
                panic!("request root snapshot should be an array");
            };
            assert_eq!(array.get(ArrayKey::string(key)), Some(&expected));
        }

        unsafe fn assert_missing(snapshot: NativeValueHandle, key: &str) {
            let Some(Value::Array(array)) = (unsafe { snapshot.as_ref() }) else {
                panic!("request root snapshot should be an array");
            };
            assert_eq!(array.get(ArrayKey::string(key)), None);
        }

        unsafe fn assert_order(snapshot: NativeValueHandle, expected: &[&str]) {
            let Some(Value::Array(array)) = (unsafe { snapshot.as_ref() }) else {
                panic!("request root snapshot should be an array");
            };
            let names: Vec<&str> = array
                .entries()
                .iter()
                .map(|entry| match &entry.key {
                    ArrayKey::String(name) => name.as_str(),
                    other => panic!("expected string request key, got {other:?}"),
                })
                .collect();
            assert_eq!(names, expected);
        }

        let request_state = phpc_native_request_state_empty();
        let get_root = unsafe { string_handle(b"_GET") };
        let cookie_root = unsafe { string_handle(b"_COOKIE") };
        let server_root = unsafe { string_handle(b"_SERVER") };
        let files_root = unsafe { string_handle(b"_FILES") };
        let request_root = unsafe { string_handle(b"_REQUEST") };
        let invalid_root = unsafe { string_handle(b"_NOPE") };
        let order_cg = unsafe { string_handle(b"CG") };

        let get_source = phpc_native_symbol_table_new();
        unsafe {
            write_symbol(get_source, b"id", Value::String("get".to_string()));
            write_symbol(get_source, b"page", Value::Int(7));
        }
        assert!(unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                get_root,
                get_source,
            )
        });

        unsafe {
            write_symbol(get_source, b"id", Value::String("get-mutated".to_string()));
            write_symbol(
                get_source,
                b"late",
                Value::String("late-source".to_string()),
            );
        }
        let get_snapshot = unsafe { snapshot(request_state, get_root) };
        unsafe {
            assert_slot(get_snapshot, "id", Value::String("get".to_string()));
            assert_slot(get_snapshot, "page", Value::Int(7));
            assert_missing(get_snapshot, "late");
            assert_order(get_snapshot, &["id", "page"]);
        }

        let server_snapshot = {
            assert!(unsafe {
                phpc_native_request_state_populate_superglobal_from_symbol_table(
                    request_state,
                    server_root,
                    get_source,
                )
            });
            unsafe { snapshot(request_state, server_root) }
        };
        unsafe {
            assert_slot(
                server_snapshot,
                "id",
                Value::String("get-mutated".to_string()),
            );
            assert_slot(
                server_snapshot,
                "late",
                Value::String("late-source".to_string()),
            );
            assert_order(server_snapshot, &["id", "page", "late"]);
        }

        let cookie_source = phpc_native_symbol_table_new();
        unsafe {
            write_symbol(
                cookie_source,
                b"id",
                Value::String("cookie-stale".to_string()),
            );
            write_symbol(cookie_source, b"stale", Value::String("stale".to_string()));
        }
        assert!(unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                cookie_root,
                cookie_source,
            )
        });

        let cookie_replacement = phpc_native_symbol_table_new();
        unsafe {
            write_symbol(
                cookie_replacement,
                b"id",
                Value::String("cookie".to_string()),
            );
            write_symbol(
                cookie_replacement,
                b"sid",
                Value::String("cookie-session".to_string()),
            );
        }
        assert!(unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                cookie_root,
                cookie_replacement,
            )
        });
        let cookie_snapshot = unsafe { snapshot(request_state, cookie_root) };
        unsafe {
            assert_slot(cookie_snapshot, "id", Value::String("cookie".to_string()));
            assert_slot(
                cookie_snapshot,
                "sid",
                Value::String("cookie-session".to_string()),
            );
            assert_missing(cookie_snapshot, "stale");
        }

        let mut upload = PhpArray::new();
        upload.insert(
            ArrayKey::string("name"),
            Value::String("file.txt".to_string()),
        );
        let files_source = phpc_native_symbol_table_new();
        unsafe {
            write_symbol(files_source, b"upload", Value::Array(upload.clone()));
        }
        assert!(unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                files_root,
                files_source,
            )
        });
        let files_snapshot = unsafe { snapshot(request_state, files_root) };
        unsafe {
            assert_slot(files_snapshot, "upload", Value::Array(upload));
        }

        let request_source = phpc_native_symbol_table_new();
        unsafe {
            write_symbol(
                request_source,
                b"manual",
                Value::String("manual-request".to_string()),
            );
        }
        assert!(unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                request_root,
                request_source,
            )
        });
        let manual_request_snapshot = unsafe { snapshot(request_state, request_root) };
        unsafe {
            assert_slot(
                manual_request_snapshot,
                "manual",
                Value::String("manual-request".to_string()),
            );
        }

        assert!(unsafe {
            phpc_native_request_state_rebuild_request_from_order(request_state, order_cg)
        });
        let rebuilt_request_snapshot = unsafe { snapshot(request_state, request_root) };
        unsafe {
            assert_slot(
                rebuilt_request_snapshot,
                "id",
                Value::String("get".to_string()),
            );
            assert_slot(
                rebuilt_request_snapshot,
                "sid",
                Value::String("cookie-session".to_string()),
            );
            assert_missing(rebuilt_request_snapshot, "manual");
            assert_missing(rebuilt_request_snapshot, "stale");
        }

        assert!(!unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                NativeRequestStateHandle::null(),
                get_root,
                get_source,
            )
        });
        assert!(!unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                invalid_root,
                get_source,
            )
        });
        assert!(!unsafe {
            phpc_native_request_state_populate_superglobal_from_symbol_table(
                request_state,
                get_root,
                NativeSymbolTableHandle::null(),
            )
        });

        unsafe { phpc_native_value_free(get_snapshot) };
        unsafe { phpc_native_value_free(server_snapshot) };
        unsafe { phpc_native_value_free(cookie_snapshot) };
        unsafe { phpc_native_value_free(files_snapshot) };
        unsafe { phpc_native_value_free(manual_request_snapshot) };
        unsafe { phpc_native_value_free(rebuilt_request_snapshot) };
        unsafe { phpc_native_symbol_table_free(get_source) };
        unsafe { phpc_native_symbol_table_free(cookie_source) };
        unsafe { phpc_native_symbol_table_free(cookie_replacement) };
        unsafe { phpc_native_symbol_table_free(files_source) };
        unsafe { phpc_native_symbol_table_free(request_source) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_string_free(cookie_root) };
        unsafe { phpc_native_string_free(server_root) };
        unsafe { phpc_native_string_free(files_root) };
        unsafe { phpc_native_string_free(request_root) };
        unsafe { phpc_native_string_free(invalid_root) };
        unsafe { phpc_native_string_free(order_cg) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_symbol_and_request_reference_slots_share_cells_across_roots() {
        unsafe fn string_handle(bytes: &[u8]) -> NativeStringHandle {
            unsafe { phpc_native_string_from_bytes(bytes.as_ptr(), bytes.len()) }
        }

        unsafe fn value_handle(value: Value) -> NativeValueHandle {
            NativeValueHandle::from_value(value)
        }

        unsafe fn write_symbol(table: NativeSymbolTableHandle, name: &[u8], value: Value) {
            let value = unsafe { value_handle(value) };
            assert!(unsafe {
                phpc_native_symbol_table_write(table, name.as_ptr(), name.len(), value)
            });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn read_symbol(table: NativeSymbolTableHandle, name: &[u8]) -> NativeValueHandle {
            unsafe { phpc_native_symbol_table_read(table, name.as_ptr(), name.len()) }
        }

        unsafe fn assert_value(handle: NativeValueHandle, expected: Value) {
            assert_eq!(unsafe { handle.as_ref() }, Some(&expected));
            unsafe { phpc_native_value_free(handle) };
        }

        unsafe fn set_reference_value(reference: NativeReferenceHandle, value: Value) {
            let value = unsafe { value_handle(value) };
            assert!(unsafe { phpc_native_reference_set_value(reference, value) });
            unsafe { phpc_native_value_free(value) };
        }

        unsafe fn assert_snapshot_slot(snapshot: NativeValueHandle, key: &str, expected: Value) {
            let Some(Value::Array(array)) = (unsafe { snapshot.as_ref() }) else {
                panic!("snapshot should be an array");
            };
            assert_eq!(array.get_cloned(ArrayKey::string(key)), Some(expected));
        }

        let symbols = phpc_native_symbol_table_new();
        unsafe { write_symbol(symbols, b"root", Value::String("initial".to_string())) };

        let root_reference =
            unsafe { phpc_native_symbol_table_reference_for_slot(symbols, b"root".as_ptr(), 4) };
        assert!(!phpc_native_reference_is_null(root_reference));
        unsafe { set_reference_value(root_reference, Value::String("from-ref".to_string())) };
        unsafe {
            assert_value(
                read_symbol(symbols, b"root"),
                Value::String("from-ref".to_string()),
            );
        }

        assert!(unsafe {
            phpc_native_symbol_table_set_reference(symbols, b"alias".as_ptr(), 5, root_reference)
        });
        unsafe { set_reference_value(root_reference, Value::String("shared".to_string())) };
        unsafe {
            assert_value(
                read_symbol(symbols, b"root"),
                Value::String("shared".to_string()),
            );
            assert_value(
                read_symbol(symbols, b"alias"),
                Value::String("shared".to_string()),
            );
        }

        let created_reference =
            unsafe { phpc_native_symbol_table_reference_for_slot(symbols, b"created".as_ptr(), 7) };
        assert!(!phpc_native_reference_is_null(created_reference));
        unsafe { set_reference_value(created_reference, Value::Int(42)) };
        unsafe {
            assert_value(read_symbol(symbols, b"created"), Value::Int(42));
        }

        let symbol_snapshot = unsafe { phpc_native_symbol_table_snapshot_value(symbols) };
        unsafe {
            assert_snapshot_slot(symbol_snapshot, "root", Value::String("shared".to_string()));
            assert_snapshot_slot(
                symbol_snapshot,
                "alias",
                Value::String("shared".to_string()),
            );
            assert_snapshot_slot(symbol_snapshot, "created", Value::Int(42));
        }
        unsafe { set_reference_value(root_reference, Value::String("after-snapshot".to_string())) };
        unsafe {
            assert_snapshot_slot(symbol_snapshot, "root", Value::String("shared".to_string()));
        }

        let request_state = phpc_native_request_state_empty();
        let get_root = unsafe { string_handle(b"_GET") };
        let post_root = unsafe { string_handle(b"_POST") };
        let invalid_root = unsafe { string_handle(b"_NOPE") };
        let id_name = unsafe { string_handle(b"id") };
        let alias_name = unsafe { string_handle(b"alias") };
        let invalid_name = unsafe { string_handle(&[0xff]) };

        let request_reference = unsafe {
            phpc_native_request_state_superglobal_reference_for_slot(
                request_state,
                get_root,
                id_name,
            )
        };
        assert!(!phpc_native_reference_is_null(request_reference));
        unsafe {
            set_reference_value(request_reference, Value::String("request-ref".to_string()));
            assert_value(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_GET".as_ptr(),
                    b"_GET".len(),
                    b"id".as_ptr(),
                    b"id".len(),
                ),
                Value::String("request-ref".to_string()),
            );
        }

        assert!(unsafe {
            phpc_native_request_state_superglobal_set_reference(
                request_state,
                post_root,
                alias_name,
                root_reference,
            )
        });
        unsafe {
            set_reference_value(
                root_reference,
                Value::String("shared-with-post".to_string()),
            );
            assert_value(
                phpc_native_request_state_superglobal_value(
                    request_state,
                    b"_POST".as_ptr(),
                    b"_POST".len(),
                    b"alias".as_ptr(),
                    b"alias".len(),
                ),
                Value::String("shared-with-post".to_string()),
            );
        }

        let get_snapshot = unsafe {
            phpc_native_request_state_superglobal_snapshot_value(request_state, get_root)
        };
        let post_snapshot = unsafe {
            phpc_native_request_state_superglobal_snapshot_value(request_state, post_root)
        };
        unsafe {
            assert_snapshot_slot(get_snapshot, "id", Value::String("request-ref".to_string()));
            assert_snapshot_slot(
                post_snapshot,
                "alias",
                Value::String("shared-with-post".to_string()),
            );
        }

        assert!(unsafe {
            phpc_native_symbol_table_reference_for_slot(
                NativeSymbolTableHandle::null(),
                b"root".as_ptr(),
                4,
            )
        }
        .is_null());
        assert!(!unsafe {
            phpc_native_symbol_table_set_reference(
                NativeSymbolTableHandle::null(),
                b"root".as_ptr(),
                4,
                root_reference,
            )
        });
        assert!(unsafe {
            phpc_native_request_state_superglobal_reference_for_slot(
                NativeRequestStateHandle::null(),
                get_root,
                id_name,
            )
        }
        .is_null());
        assert!(unsafe {
            phpc_native_request_state_superglobal_reference_for_slot(
                request_state,
                invalid_root,
                id_name,
            )
        }
        .is_null());
        assert!(unsafe {
            phpc_native_request_state_superglobal_reference_for_slot(
                request_state,
                get_root,
                invalid_name,
            )
        }
        .is_null());
        assert!(!unsafe {
            phpc_native_request_state_superglobal_set_reference(
                request_state,
                get_root,
                id_name,
                NativeReferenceHandle::null(),
            )
        });

        unsafe { phpc_native_value_free(symbol_snapshot) };
        unsafe { phpc_native_value_free(get_snapshot) };
        unsafe { phpc_native_value_free(post_snapshot) };
        unsafe { phpc_native_reference_free(root_reference) };
        unsafe { phpc_native_reference_free(created_reference) };
        unsafe { phpc_native_reference_free(request_reference) };
        unsafe { phpc_native_symbol_table_free(symbols) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_string_free(post_root) };
        unsafe { phpc_native_string_free(invalid_root) };
        unsafe { phpc_native_string_free(id_name) };
        unsafe { phpc_native_string_free(alias_name) };
        unsafe { phpc_native_string_free(invalid_name) };
        unsafe { phpc_native_request_state_free(request_state) };
    }

    #[test]
    fn native_request_state_operation_result_diagnostic_covers_status_family() {
        for result in [
            NativeRequestStateOperationResult::value(
                Value::String("ok".to_string()),
                true,
                true,
                NativeRequestStateOperationStatus::Ok,
            ),
            NativeRequestStateOperationResult::array(
                PhpArray::new(),
                true,
                NativeRequestStateOperationStatus::Ok,
            ),
            NativeRequestStateOperationResult::presence(
                true,
                true,
                NativeRequestStateOperationStatus::Ok,
            ),
            NativeRequestStateOperationResult::presence(
                false,
                false,
                NativeRequestStateOperationStatus::MissingKey,
            ),
            NativeRequestStateOperationResult::bag_presence(
                true,
                NativeRequestStateOperationStatus::Ok,
            ),
        ] {
            let diagnostic = phpc_native_request_state_operation_result_diagnostic(result);

            assert!(diagnostic.is_null());
            unsafe { phpc_native_request_state_operation_result_free(result) };
            unsafe { phpc_native_diagnostic_free(diagnostic) };
        }

        let missing_value = NativeRequestStateOperationResult::value(
            Value::Null,
            false,
            false,
            NativeRequestStateOperationStatus::MissingKey,
        );
        let missing_diagnostic =
            phpc_native_request_state_operation_result_diagnostic(missing_value);
        assert!(!missing_diagnostic.is_null());
        assert_eq!(
            native_diagnostic_message_for_test(missing_diagnostic),
            NATIVE_REQUEST_STATE_MISSING_KEY_READ_MESSAGE
        );
        assert_eq!(
            unsafe { phpc_native_diagnostic_severity_at(missing_diagnostic, 0) },
            NativeDiagnosticSeverity::Warning.tag()
        );
        unsafe { phpc_native_request_state_operation_result_free(missing_value) };
        unsafe { phpc_native_diagnostic_free(missing_diagnostic) };

        let request_state = phpc_native_request_state_empty();
        let get_root = NativeStringHandle::from_vec(b"_GET".to_vec());
        let key = NativeStringHandle::from_vec(b"absent".to_vec());
        let missing_read = unsafe {
            phpc_native_request_state_superglobal_operation(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_VALUE,
                phpc_native_string_bytes(get_root),
                phpc_native_string_len(get_root),
                phpc_native_string_bytes(key),
                phpc_native_string_len(key),
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
            )
        };
        assert_eq!(
            phpc_native_request_state_operation_result_report_diagnostic(missing_read),
            NATIVE_REQUEST_STATE_MISSING_KEY_READ_MESSAGE.len()
        );
        unsafe { phpc_native_request_state_operation_result_free(missing_read) };

        let missing_presence = unsafe {
            phpc_native_request_state_superglobal_operation(
                request_state,
                PHPC_NATIVE_REQUEST_STATE_OP_PRESENCE,
                phpc_native_string_bytes(get_root),
                phpc_native_string_len(get_root),
                phpc_native_string_bytes(key),
                phpc_native_string_len(key),
                PHPC_NATIVE_REQUEST_STATE_STATUS_OK,
            )
        };
        assert_eq!(
            phpc_native_request_state_operation_result_report_diagnostic(missing_presence),
            0
        );
        unsafe { phpc_native_request_state_operation_result_free(missing_presence) };
        unsafe { phpc_native_string_free(key) };
        unsafe { phpc_native_string_free(get_root) };
        unsafe { phpc_native_request_state_free(request_state) };

        for (status, expected) in [
            (
                NativeRequestStateOperationStatus::InvalidOperation,
                "native request-state operation failed: invalid operation tag",
            ),
            (
                NativeRequestStateOperationStatus::InvalidAbi,
                "native request-state operation failed: invalid ABI operands",
            ),
            (
                NativeRequestStateOperationStatus::NullState,
                "native request-state operation failed: null request state",
            ),
            (
                NativeRequestStateOperationStatus::UnknownBag,
                "native request-state operation failed: unknown request bag",
            ),
            (
                NativeRequestStateOperationStatus::UnsupportedKeyedBag,
                "native request-state operation failed: keyed access is not supported for this request bag",
            ),
            (
                NativeRequestStateOperationStatus::UnsupportedKeyCoercion,
                "native request-state operation failed: unsupported PHP key coercion",
            ),
            (
                NativeRequestStateOperationStatus::UnsupportedKeyedValue,
                "native request-state operation failed: keyed request-state value is not array-accessible",
            ),
        ] {
            let result = NativeRequestStateOperationResult::unsupported(status);
            let diagnostic = phpc_native_request_state_operation_result_diagnostic(result);

            assert!(!diagnostic.is_null());
            assert_eq!(native_diagnostic_message_for_test(diagnostic), expected);

            unsafe { phpc_native_diagnostic_free(diagnostic) };
        }

        let invalid_status = NativeRequestStateOperationResult {
            status: 0,
            ..NativeRequestStateOperationResult::null()
        };
        let diagnostic = phpc_native_request_state_operation_result_diagnostic(invalid_status);
        assert!(!diagnostic.is_null());
        assert_eq!(
            native_diagnostic_message_for_test(diagnostic),
            "native request-state operation failed: invalid result status"
        );

        unsafe { phpc_native_diagnostic_free(diagnostic) };
    }

